// to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
// copies of the Software, and to permit persons to whom the Software is
// furnished to do so, subject to the following conditions:
// 
// The above copyright notice and this permission notice shall be included in all
// copies or substantial portions of the Software.
// 
// THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
// IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
// FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
// AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
// LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
// OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
// SOFTWARE.


(function () {
  'use strict';
  if (window.top !== window.self) return;

  const STORAGE_KEY = 'gemini_auto_select_cfg_v1';
  const DEFAULTS = Object.freeze({
    model: '',
    thinking: '',
    debug: false,
  });

  const NEW_CHAT_PATH_RX = /^\/(app|u\/\d+\/app)?\/?$/;
  const NEW_CHAT_BTN_SELECTOR =
    'a[href$="/app"], a[href*="/app?"], [data-test-id="new-chat-button"], [aria-label*="New chat" i]';
  const MODEL_BUTTON_SELECTORS = [
    'button[data-test-id="bard-mode-menu-button"]',
    '[data-test-id="bard-mode-menu-button"] button',
    '.model-picker-container button',
    'button[aria-label*="Open mode picker" i]',
  ];
  const PROMPT_INPUT_SELECTOR =
    'rich-textarea .ql-editor[contenteditable="true"], rich-textarea [contenteditable="true"], [role="textbox"][contenteditable="true"], textarea[aria-label]';
  const MENU_ROOT_SELECTOR = '.cdk-overlay-pane, [role="menu"], [role="listbox"], :popover-open';
  const TAKEOVER_PICKER_SELECTOR = [...MODEL_BUTTON_SELECTORS, MENU_ROOT_SELECTOR].join(', ');
  const MENU_ITEM_SELECTOR =
    'gem-menu-item[data-mode], gem-menu-item[role="menuitemradio"], gem-menu-item, [role="menuitemradio"], [role="menuitem"], [role="option"]';
  const THINKING_KEYWORDS = ['thinking', 'reasoning', 'effort'];
  const OBSERVER_ATTR_FILTER = [
    'class',
    'style',
    'hidden',
    'disabled',
    'aria-disabled',
    'aria-checked',
    'aria-selected',
    'aria-expanded',
    'aria-controls',
    'aria-label',
  ];

  let cachedConfig = null;

  function loadConfig() {
    try {
      const raw = GM_getValue(STORAGE_KEY, null);
      const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (parsed && typeof parsed === 'object') {
        return {
          model: typeof parsed.model === 'string' ? parsed.model : DEFAULTS.model,
          thinking: typeof parsed.thinking === 'string' ? parsed.thinking : DEFAULTS.thinking,
          debug: typeof parsed.debug === 'boolean' ? parsed.debug : DEFAULTS.debug,
        };
      }
    } catch (_) {}
    return { ...DEFAULTS };
  }

  function getConfig() {
    if (!cachedConfig) cachedConfig = loadConfig();
    return cachedConfig;
  }

  function saveConfig(cfg) {
    cachedConfig = { ...cfg };
    GM_setValue(STORAGE_KEY, cachedConfig);
  }

  let debugEnabled = getConfig().debug;
  const log = (...args) => {
    if (debugEnabled) console.log('[Gemini Auto Select]', ...args);
  };

  const norm = (s) => (s || '').replace(/\s+/g, ' ').trim().toLowerCase();
  const escapeRx = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const getItemText = (el) => (el?.innerText || el?.textContent || '').replace(/\s+/g, ' ').trim();

  const wordRegexCache = new Map();

  function matchesWord(haystack, needle) {
    const cleanNeedle = norm(needle);
    if (!cleanNeedle) return false;
    let rx = wordRegexCache.get(cleanNeedle);
    if (!rx) {
      if (wordRegexCache.size > 64) wordRegexCache.clear();
      rx = new RegExp(`(?<![\\p{L}\\p{N}_-])${escapeRx(cleanNeedle)}(?![\\p{L}\\p{N}_-])`, 'iu');
      wordRegexCache.set(cleanNeedle, rx);
    }
    return rx.test(norm(haystack));
  }

  function isVisible(el) {
    if (!el || !el.isConnected) return false;
    if (typeof el.checkVisibility === 'function') {
      return (
        el.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true }) &&
        el.getClientRects().length > 0
      );
    }
    const rect = el.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
  }

  function clickEl(el) {
    if (!el) return;
    const inner =
      el.tagName === 'GEM-MENU-ITEM' || el.tagName === 'GEM-BUTTON'
        ? el.querySelector('button, [role="menuitem"], [role="menuitemradio"]') || el
        : el;
    inner.click();
  }

  function pointerClickEl(el) {
    if (!el) return;
    if (typeof PointerEvent === 'function') {
      el.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true, composed: true }));
    }
    el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, composed: true }));
    if (typeof PointerEvent === 'function') {
      el.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, cancelable: true, composed: true }));
    }
    el.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, composed: true }));
    el.click();
  }

  function hoverAndClick(el) {
    if (!el) return;
    for (const type of ['pointerenter', 'mouseenter', 'pointerover', 'mouseover']) {
      el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true }));
    }
    clickEl(el);
  }

  function dispatchEscape() {
    const target =
      document.activeElement && document.activeElement !== document.body
        ? document.activeElement
        : document.body || document.documentElement;
    const init = {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
      which: 27,
      bubbles: true,
      cancelable: true,
      composed: true,
    };
    target.dispatchEvent(new KeyboardEvent('keydown', init));
    target.dispatchEvent(new KeyboardEvent('keyup', init));
  }

  function sleep(ms, signal) {
    return new Promise((resolve) => {
      if (signal?.aborted) return resolve();
      const onAbort = () => {
        clearTimeout(id);
        resolve();
      };
      const id = setTimeout(() => {
        signal?.removeEventListener('abort', onAbort);
        resolve();
      }, ms);
      signal?.addEventListener('abort', onAbort, { once: true });
    });
  }

  // Scopes menu observations to Angular CDK's overlay container (+ picker wrapper for gem-popover)
  function getMenuObserverRoots(pickerBtn) {
    const overlay = document.querySelector('.cdk-overlay-container');
    if (!overlay) return [document.body || document.documentElement];
    const roots = [overlay];
    const wrapper = pickerBtn?.parentElement;
    if (wrapper?.isConnected) {
      roots.push(wrapper);
    } else if (pickerBtn?.isConnected) {
      roots.push(pickerBtn);
    }
    return roots;
  }

  // rAF-coalesced, self-disconnecting DOM observer with an active-only poll fallback
  // (handles native :popover-open toggles, CSS opacity transitions, and out-of-root portals)
  function waitFor(fn, { root, timeout = 8000, attributes = true, pollInterval = 80, signal } = {}) {
    if (signal?.aborted) return Promise.resolve(null);
    const immediate = fn();
    if (immediate) return Promise.resolve(immediate);

    return new Promise((resolve) => {
      let settled = false;
      let rafId = null;
      let settleTimer = null;
      let pollTimer = null;
      let timer = null;

      const rawRoots = Array.isArray(root) ? root : [root];
      const targets = rawRoots.filter((n) => n && n.isConnected);
      if (targets.length === 0) {
        const fallback = document.body || document.documentElement;
        if (fallback) targets.push(fallback);
      }

      const finish = (val) => {
        if (settled) return;
        settled = true;
        obs.disconnect();
        if (rafId !== null) cancelAnimationFrame(rafId);
        if (timer) clearTimeout(timer);
        if (settleTimer) clearTimeout(settleTimer);
        if (pollTimer) clearInterval(pollTimer);
        signal?.removeEventListener('abort', onAbort);
        resolve(val);
      };

      const onAbort = () => finish(null);

      const check = () => {
        if (settled) return true;
        const res = fn();
        if (res) {
          finish(res);
          return true;
        }
        return false;
      };

      const onMutation = () => {
        if (rafId === null) {
          rafId = requestAnimationFrame(() => {
            rafId = null;
            if (check()) return;
            if (!settleTimer) {
              settleTimer = setTimeout(() => {
                settleTimer = null;
                check();
              }, 160);
            }
          });
        }
      };

      const obs = new MutationObserver(onMutation);
      const obsOpts = {
        childList: true,
        subtree: true,
        attributes,
        ...(attributes ? { attributeFilter: OBSERVER_ATTR_FILTER } : {}),
      };
      for (const target of targets) {
        obs.observe(target, obsOpts);
      }

      if (pollInterval > 0) {
        pollTimer = setInterval(check, pollInterval);
      }
      timer = setTimeout(() => finish(null), timeout);
      signal?.addEventListener('abort', onAbort, { once: true });
    });
  }

  function findModelButton() {
    for (const sel of MODEL_BUTTON_SELECTORS) {
      for (const el of document.querySelectorAll(sel)) {
        if (isVisible(el)) return el;
      }
    }
    return null;
  }

  function readCurrentSelection(pickerBtn) {
    const primaryEl = pickerBtn.querySelector('.picker-primary-text');
    const secondaryEl = pickerBtn.querySelector('.picker-secondary-text');
    const modelText = primaryEl && isVisible(primaryEl) ? getItemText(primaryEl) : '';
    const thinkingText = secondaryEl && isVisible(secondaryEl) ? getItemText(secondaryEl) : '';
    const rawAria = pickerBtn.getAttribute('aria-label') || '';
    const ariaSelection = rawAria.includes(':') ? rawAria.slice(rawAria.lastIndexOf(':') + 1).trim() : rawAria;
    return { modelText, thinkingText, ariaSelection };
  }

  function checkSelectionState(pickerBtn, targetModel, targetThinking) {
    const { modelText, thinkingText, ariaSelection } = readCurrentSelection(pickerBtn);

    const modelMatches = !targetModel
      ? true
      : modelText
        ? norm(modelText) === norm(targetModel) || matchesWord(modelText, targetModel)
        : matchesWord(ariaSelection, targetModel);

    const thinkingMatches = !targetThinking
      ? true
      : thinkingText
        ? norm(thinkingText) === norm(targetThinking) || matchesWord(thinkingText, targetThinking)
        : matchesWord(ariaSelection, targetThinking);

    return { modelMatches, thinkingMatches, modelText, thinkingText };
  }

  function findPromptInput() {
    for (const el of document.querySelectorAll(PROMPT_INPUT_SELECTOR)) {
      if (isVisible(el)) return el;
    }
    return null;
  }

  function getVisibleMenuItems(menuIds = '', { idsOnly = false } = {}) {
    const roots = [];
    const ids = Array.isArray(menuIds) ? menuIds : [menuIds];

    for (const id of ids) {
      if (!id) continue;
      const byId = document.getElementById(id);
      if (byId && isVisible(byId) && !roots.includes(byId)) roots.push(byId);
    }

    if (!idsOnly) {
      for (const pane of document.querySelectorAll(MENU_ROOT_SELECTOR)) {
        if (isVisible(pane) && !roots.includes(pane)) roots.push(pane);
      }
    }

    if (roots.length === 0) return [];

    const seen = new Set();
    const items = [];
    for (const root of roots) {
      for (const el of root.querySelectorAll(MENU_ITEM_SELECTOR)) {
        if (!seen.has(el) && isVisible(el)) {
          seen.add(el);
          items.push(el);
        }
      }
    }
    return items;
  }

  function isMenuOpen(pickerBtn, menuIds = []) {
    return pickerBtn?.getAttribute('aria-expanded') === 'true' || getVisibleMenuItems(menuIds).length > 0;
  }

  function isItemSelected(el) {
    return (
      el.getAttribute('aria-checked') === 'true' ||
      el.getAttribute('aria-selected') === 'true' ||
      el.classList.contains('selected') ||
      el.classList.contains('is-selected') ||
      !!el.querySelector(
        '[aria-checked="true"], [data-mat-icon-name="check"], [data-mat-icon-name="check_circle"], .selected, .is-selected'
      )
    );
  }

  function findMenuItemByText(target, items) {
    const needle = norm(target);
    if (!needle) return null;
    return (
      items.find((el) => norm(getItemText(el)) === needle) ||
      items.find((el) => matchesWord(getItemText(el), needle)) ||
      items.find((el) => norm(getItemText(el)).includes(needle))
    );
  }

  function findThinkingTrigger(menuId = '') {
    const exact = [...document.querySelectorAll('gem-menu-item[value="thinking_level"]')].find(isVisible);
    if (exact) return exact;

    const items = getVisibleMenuItems(menuId);
    return (
      items.find((el) => {
        const txt = norm(getItemText(el));
        const hasPopup = el.getAttribute('aria-haspopup') === 'true' || el.getAttribute('aria-haspopup') === 'menu';
        return THINKING_KEYWORDS.some((k) => txt.includes(k)) && (hasPopup || txt.includes('level'));
      }) ||
      items.find((el) => el.getAttribute('aria-haspopup') === 'true' || el.getAttribute('aria-haspopup') === 'menu')
    );
  }

  async function openModelMenu(pickerBtn, signal) {
    let menuId = pickerBtn.getAttribute('aria-controls') || '';
    const backoffs = [120, 250, 450];

    for (let attempt = 0; attempt < backoffs.length; attempt++) {
      if (signal.aborted) return { items: null, menuId };

      const existing = getVisibleMenuItems(menuId);
      if (existing.length > 0) return { items: existing, menuId };

      clickEl(pickerBtn);
      const items = await waitFor(
        () => {
          menuId = pickerBtn.getAttribute('aria-controls') || menuId;
          const found = getVisibleMenuItems(menuId);
          return found.length > 0 ? found : null;
        },
        { root: getMenuObserverRoots(pickerBtn), attributes: true, timeout: 900, signal }
      );

      if (items) return { items, menuId };
      await sleep(backoffs[attempt], signal);
    }
    return { items: null, menuId };
  }

  function focusPromptInput() {
    const input = findPromptInput();
    if (!input) return;

    const applyFocus = () => {
      const active = document.activeElement;
      const userTypingElsewhere =
        active &&
        active !== input &&
        (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.isContentEditable);
      if (!userTypingElsewhere && isVisible(input)) {
        input.focus({ preventScroll: true });
      }
    };

    applyFocus();
    requestAnimationFrame(() => applyFocus());
  }

  async function closeMenuAndFocusInput(pickerBtn, menuIds, signal) {
    const strategies = [
      () => {
        const backdrop = document.querySelector(
          '.cdk-overlay-backdrop.cdk-overlay-backdrop-showing, .cdk-overlay-backdrop'
        );
        if (backdrop && isVisible(backdrop)) {
          pointerClickEl(backdrop);
        } else {
          dispatchEscape();
        }
      },
      () => dispatchEscape(),
      () => {
        const input = findPromptInput();
        if (input) pointerClickEl(input);
        else dispatchEscape();
      },
      () => {
        if (pickerBtn?.getAttribute('aria-expanded') === 'true') {
          clickEl(pickerBtn);
        }
      },
    ];

    for (const step of strategies) {
      if (signal.aborted || !isMenuOpen(pickerBtn, menuIds)) break;
      step();
      await waitFor(() => !isMenuOpen(pickerBtn, menuIds), {
        root: getMenuObserverRoots(pickerBtn),
        attributes: true,
        timeout: 220,
        signal,
      });
    }

    if (!signal.aborted) {
      focusPromptInput();
    }
  }

  async function applyModelAndThinking(cfg, signal) {
    if (!cfg.model && !cfg.thinking) {
      log('No default model or thinking level configured; use "Gemini Auto Select: Configure" to set them.');
      return true;
    }

    const pickerBtn = await waitFor(
      () => {
        const btn = findModelButton();
        if (!btn || btn.getAttribute('aria-disabled') === 'true') return null;
        const { modelText, ariaSelection } = readCurrentSelection(btn);
        return modelText || ariaSelection ? btn : null;
      },
      { timeout: 10000, signal }
    );
    if (!pickerBtn || signal.aborted) {
      log('Model picker button not found');
      return false;
    }

    // Zero-click early exit when both model and thinking level already match
    const initial = checkSelectionState(pickerBtn, cfg.model, cfg.thinking);
    if (initial.modelMatches && initial.thinkingMatches) {
      log(`Already on target (${initial.modelText} ${initial.thinkingText}); skipping`);
      return true;
    }

    const { items: menuItems, menuId } = await openModelMenu(pickerBtn, signal);
    if (!menuItems || signal.aborted) {
      log('Model menu did not open');
      return false;
    }

    const trackedMenuIds = new Set(menuId ? [menuId] : []);

    // 1. Select Model (only if not already active)
    if (cfg.model && !initial.modelMatches) {
      const modelItem = findMenuItemByText(cfg.model, menuItems);
      if (modelItem) {
        if (!isItemSelected(modelItem)) {
          log(`Selecting model: ${cfg.model}`);
          clickEl(modelItem);
          await waitFor(
            () =>
              !isVisible(modelItem) ||
              isItemSelected(modelItem) ||
              checkSelectionState(findModelButton() || pickerBtn, cfg.model, '').modelMatches,
            { root: getMenuObserverRoots(pickerBtn), attributes: true, timeout: 700, signal }
          );
        } else {
          log(`Model already selected: ${cfg.model}`);
        }
      } else {
        log('Model not found:', cfg.model, '| Visible:', menuItems.map(getItemText));
      }
    }

    if (signal.aborted) return false;

    // Re-check pill after model switch: switching models often restores the target thinking level
    const currentBtn = findModelButton() || pickerBtn;
    const afterModel = checkSelectionState(currentBtn, cfg.model, cfg.thinking);

    // 2. Select Thinking Level (only if not already active)
    if (cfg.thinking && !afterModel.thinkingMatches) {
      let activeMenuId = menuId;
      let thinkingTrigger = findThinkingTrigger(activeMenuId);

      // Re-open menu if selecting the model closed it
      if (!thinkingTrigger) {
        await waitFor(() => getVisibleMenuItems([...trackedMenuIds]).length === 0, {
          root: getMenuObserverRoots(currentBtn),
          attributes: true,
          timeout: 300,
          signal,
        });
        if (signal.aborted) return false;

        const reopenBtn = findModelButton() || currentBtn;
        const reopened = await openModelMenu(reopenBtn, signal);
        if (reopened.items) {
          activeMenuId = reopened.menuId;
          if (activeMenuId) trackedMenuIds.add(activeMenuId);
          thinkingTrigger = findThinkingTrigger(activeMenuId);
        }
      }

      if (thinkingTrigger && !signal.aborted) {
        if (thinkingTrigger.getAttribute('aria-disabled') === 'true') {
          log('Thinking level control is disabled for this model');
        } else {
          const parentItems = new Set(getVisibleMenuItems([...trackedMenuIds]));
          log('Opening thinking submenu:', getItemText(thinkingTrigger));
          hoverAndClick(thinkingTrigger);

          const thinkingOption = await waitFor(
            () => {
              const subMenuId = thinkingTrigger.getAttribute('aria-controls') || '';
              if (subMenuId) {
                trackedMenuIds.add(subMenuId);
                const scopedItems = getVisibleMenuItems(subMenuId, { idsOnly: true });
                if (scopedItems.length > 0) {
                  return findMenuItemByText(cfg.thinking, scopedItems);
                }
              }

              const allItems = getVisibleMenuItems([...trackedMenuIds]).filter(
                (el) => el !== thinkingTrigger
              );
              const newItems = allItems.filter((el) => !parentItems.has(el));
              return findMenuItemByText(cfg.thinking, newItems.length > 0 ? newItems : allItems);
            },
            { root: getMenuObserverRoots(currentBtn), attributes: true, timeout: 2000, signal }
          );

          if (thinkingOption && !signal.aborted) {
            if (!isItemSelected(thinkingOption)) {
              log(`Selecting thinking level: ${cfg.thinking}`);
              clickEl(thinkingOption);
              await waitFor(
                () =>
                  !isVisible(thinkingOption) ||
                  isItemSelected(thinkingOption) ||
                  checkSelectionState(findModelButton() || currentBtn, '', cfg.thinking).thinkingMatches,
                { root: getMenuObserverRoots(currentBtn), attributes: true, timeout: 400, signal }
              );
            } else {
              log(`Thinking level already selected: ${cfg.thinking}`);
            }
          } else {
            log(
              'Thinking level not found:',
              cfg.thinking,
              '| Visible:',
              getVisibleMenuItems([...trackedMenuIds]).map(getItemText)
            );
          }
        }
      } else if (!signal.aborted) {
        log('Thinking trigger not found | Visible:', getVisibleMenuItems([...trackedMenuIds]).map(getItemText));
      }
    } else if (cfg.thinking && afterModel.thinkingMatches) {
      log(`Thinking level already active (${afterModel.thinkingText}); skipping submenu`);
    }

    if (signal.aborted) return false;

    await closeMenuAndFocusInput(findModelButton() || currentBtn, [...trackedMenuIds], signal);
    return !signal.aborted;
  }

  let activeController = null;
  let activeRunUrl = '';
  let lastRunUrl = '';
  let waitingForVisibility = false;
  let newChatTimer = null;

  const onVisibilityChange = () => {
    if (document.visibilityState === 'visible') {
      document.removeEventListener('visibilitychange', onVisibilityChange);
      waitingForVisibility = false;
      run(false);
    }
  };

  async function run(force = false) {
    const runUrl = location.href;
    if (!force && !NEW_CHAT_PATH_RX.test(location.pathname)) return;
    if (!force && (lastRunUrl === runUrl || activeRunUrl === runUrl)) return;

    // Defer execution in background or prerendered tabs until actually visible
    if (!force && document.visibilityState !== 'visible') {
      if (!waitingForVisibility) {
        waitingForVisibility = true;
        document.addEventListener('visibilitychange', onVisibilityChange);
      }
      return;
    }

    if (waitingForVisibility) {
      document.removeEventListener('visibilitychange', onVisibilityChange);
      waitingForVisibility = false;
    }

    activeController?.abort();
    const controller = new AbortController();
    activeController = controller;
    activeRunUrl = runUrl;

    const cfg = getConfig();
    debugEnabled = cfg.debug;
    log('Running v1.0.0:', cfg);

    // Abort immediately if the user manually interacts with the menu or starts typing
    const onUserTakeover = (e) => {
      if (!e.isTrusted) return;
      if (e.type === 'keydown') {
        if (e.ctrlKey || e.metaKey || e.altKey || e.key === 'Escape' || e.key === 'Tab') return;
        if (e.target instanceof Element && e.target.closest(PROMPT_INPUT_SELECTOR)) {
          log('Aborted: user started typing');
          controller.abort();
        }
      } else if (e.type === 'pointerdown') {
        if (e.target instanceof Element && e.target.closest(TAKEOVER_PICKER_SELECTOR)) {
          log('Aborted: user interacted with picker');
          controller.abort();
        }
      }
    };

    document.addEventListener('keydown', onUserTakeover, { capture: true, passive: true });
    document.addEventListener('pointerdown', onUserTakeover, { capture: true, passive: true });

    try {
      const completed = await applyModelAndThinking(cfg, controller.signal);
      if (completed && !controller.signal.aborted && location.href === runUrl) {
        lastRunUrl = runUrl;
      }
    } catch (err) {
      console.error('[Gemini Auto Select] Error during execution:', err);
    } finally {
      document.removeEventListener('keydown', onUserTakeover, true);
      document.removeEventListener('pointerdown', onUserTakeover, true);
      if (activeController === controller) {
        activeController = null;
        activeRunUrl = '';
      }
    }
  }

  GM_registerMenuCommand('Gemini Auto Select: Configure', () => {
    const cfg = getConfig();
    const model = prompt('Default model (e.g. Fast, Thinking, Pro; leave empty to skip):', cfg.model);
    if (model === null) return;
    const thinking = prompt('Default thinking level (e.g. High, Medium, Low; leave empty to skip):', cfg.thinking);
    if (thinking === null) return;
    saveConfig({
      ...cfg,
      model: model.trim(),
      thinking: thinking.trim(),
    });
    run(true);
  });

  GM_registerMenuCommand('Gemini Auto Select: Run Now', () => run(true));

  GM_registerMenuCommand('Gemini Auto Select: Toggle Debug Logs', () => {
    const nextCfg = { ...getConfig(), debug: !getConfig().debug };
    debugEnabled = nextCfg.debug;
    saveConfig(nextCfg);
    console.log(`[Gemini Auto Select] Debug logs ${nextCfg.debug ? 'enabled' : 'disabled'}`);
  });

  // Zero-idle-overhead SPA route watching
  let prevHref = location.href;
  const onRouteChange = () => {
    if (location.href === prevHref) return;
    prevHref = location.href;
    activeController?.abort();
    lastRunUrl = '';
    activeRunUrl = '';
    run(false);
  };

  const nav =
    typeof window.navigation !== 'undefined' && typeof window.navigation.addEventListener === 'function'
      ? window.navigation
      : null;

  if (nav) {
    nav.addEventListener('navigatesuccess', onRouteChange);
  } else {
    window.addEventListener('popstate', onRouteChange);
  }

  const scheduleNewChatRun = (delay) => {
    activeController?.abort();
    lastRunUrl = '';
    activeRunUrl = '';
    clearTimeout(newChatTimer);
    newChatTimer = setTimeout(() => {
      newChatTimer = null;
      run(false);
    }, delay);
  };

  // Handle New Chat button clicks and Ctrl+Shift+O / Cmd+Shift+O from any route
  document.addEventListener(
    'click',
    (e) => {
      if (e.target instanceof Element && e.target.closest(NEW_CHAT_BTN_SELECTOR)) {
        scheduleNewChatRun(120);
      }
    },
    { capture: true, passive: true }
  );

  document.addEventListener(
    'keydown',
    (e) => {
      if (e.isTrusted && e.shiftKey && (e.ctrlKey || e.metaKey) && e.code === 'KeyO') {
        scheduleNewChatRun(150);
      }
    },
    { capture: true, passive: true }
  );

  run(false);
})();

