      qDone: '已抓到', qNow: (c) => `现在能抓 · ${c}`, qActive: (c) => `正在抓 · ${c}`,
      qNeed: (w, c) => `要 ${w} · ${c}`, qNowhere: '已解锁的地图里抓不到',
