      qIdle: '队列里暂时没有能抓的，推最新章节中', qAllDone: '队列都抓完了，推最新章节中', qOtherReg: (r) => `在${r}，不会跨地区去抓`, qFrontOther: '最新章节在别的地区，先留在这里',
      qCaptureOff: '游戏的自动捕捉没开，抓不到', qGot: (n, k) => `抓到了${n}！队列还剩 ${k} 只`,
      qGotAll: (n) => `抓到了${n}！队列都抓完了，回去推最新章节`, queueOn: '队列模式开着，本章的自动重玩由队列接管',
      dexAdd: '＋ 加入队列', dexIn: '✓ 已在队列', drag: '拖动排序',
    },
    en: {
      title: 'Catch Compass', tabChapter: 'Chapter', tabQueue: 'Queue',
      step: (a, b) => `Step ${a}/${b}`, indoor: 'Indoors', clear: 'No weather',
      now: 'Catchable here now', other: 'Needs another time or weather', route: 'This run',
      clearPicks: 'Clear', uncaught: 'Not caught', pickHint: 'Click a Pokémon to target it, click again to drop it',
      last: (s, n) => `Last target at step ${s}, ${n} to go`, lastHere: 'This is the last target step',
      noneAhead: 'No targets ahead', noneChapter: 'No targets here at this time and weather', noPicks: 'Click a Pokémon above to target it',
      auto: 'Replay the chapter after the targets', extra: 'Keep going for', extraUnit: 'more steps',
      willReplay: (s) => `This run replays after step ${s}`, restarted: (n) => `${n} automatic moves`,
      waitScreen: 'Continues when you return to Adventure', special: 'Not tracked in events, leagues, the tower or legend zones',
      loading: 'Waiting for the game…', noHook: 'Could not attach to the game. Reload the page.', paused: 'Several runs in a row had no targets, so auto replay is paused',
      caught: 'Caught', target: 'Target', replayAt: 'Replay point',
      got: (n) => `Caught ${n}! Auto replay is off, the run carries on`,
      types: { wild: 'Wild', static: 'Static', trainer: 'Trainer', item: 'Item', heal: 'Heal', gym: 'Gym' },
      qAuto: 'Hunt the queue automatically', qSearch: 'Search a Pokémon to queue',
      qEmpty: 'Use "Add to queue" in the Pokédex, or search above', qClearDone: 'Clear caught',
      qDone: 'Caught', qNow: (c) => `Catchable now · ${c}`, qActive: (c) => `Hunting · ${c}`,
      qNeed: (w, c) => `Needs ${w} · ${c}`, qNowhere: 'Not in any unlocked chapter',
      qHunting: (n, c) => `Hunting ${n} · ${c}`, qWaitFront: (n) => `Finishing this run first, then ${n}`,
      qIdle: 'Nothing in the queue is catchable now, pushing the newest chapter', qAllDone: 'Queue done, pushing the newest chapter', qOtherReg: (r) => `Queued for ${r}; won't cross regions`, qFrontOther: 'The newest chapter is in another region, staying here',
      qCaptureOff: "The game's auto capture is off, so nothing gets caught", qGot: (n, k) => `Caught ${n}! ${k} left in the queue`,
      qGotAll: (n) => `Caught ${n}! Queue done, heading back to the newest chapter`, queueOn: 'Queue mode is on and handles replays',
      dexAdd: '+ Add to queue', dexIn: '✓ In queue', drag: 'Drag to reorder',
    },
  };

  // ---------- Settings ----------
  const store = {
    get: (k, d) => { try { const v = localStorage.getItem('cc-' + k); return v == null ? d : JSON.parse(v); } catch { return d; } },
    set: (k, v) => { try { localStorage.setItem('cc-' + k, JSON.stringify(v)); } catch {} },
  };
  let lang = store.get('lang', /^zh/.test(localStorage.getItem('pokecatch.lang') || navigator.language) ? 'zh' : 'en');
  let tab = store.get('tab', 'chapter');
  let picks = new Set(store.get('picks', []));
  let queue = store.get('queue', []);
  let auto = store.get('auto', false);
  let qauto = store.get('qauto', false);
  let extraMin = store.get('extraMin', 0);
  let extraMax = store.get('extraMax', 2);
  const T = () => TEXT[lang];
  const saveQueue = () => store.set('queue', queue);

  // ---------- Game helpers ----------
  const tr = (s) => { try { return NS._t ? NS._t(s) : s; } catch { return s; } };
  const CATCH_TYPES = new Set(['wild', 'static']);
  const ADV = () => NS?.Game?.S?.adv;
  const special = (adv) => !!(adv.event || adv.zone || adv.league || adv.tower);
  const onAdventure = () => NS.App?.current === 'adventure';
  const inDex = (id) => { try { return !!NS.Game.inDex(id); } catch { return false; } };
  // Each region keeps its own Pokédex and box; the game's auto capture only skips species owned in the current region
  const regionOfCh = (ch) => { try { return NS.STORY.regionOf(ch)?.key || null; } catch { return null; } };
  const curRegion = () => regionOfCh(ADV().chapter);
  const regionName = (reg) => tr(NS.STORY.REGIONS?.find((r) => r.key === reg)?.name || reg || '');
  const regCaught = (id, reg) => { try { return !!NS.Game.S.dex?.[id]?.regs?.[reg]; } catch { return false; } };
  const caughtHere = (id) => regCaught(id, curRegion());
  const chapterName = (ch) => tr(NS.STORY.CHAPTERS[ch]?.name || '');

  function poolOfNode(node, ch) {
    if (!node) return [];
    if (node.type === 'static') return node.id ? [{ id: node.id, on: true }] : [];
    if (node.type !== 'wild') return [];
    try { return NS.Adventure.zonePool(node, ch, true, null, true) || []; } catch { return []; }
  }
  function stepPool(ch, steps, i) {
    try { return NS.Adventure.zonePool({ ...steps[i], lv: NS.STORY.routeBand(ch, i, steps.length) }, ch, true, null, true) || []; } catch { return []; }
  }

  // Every species one chapter can give, with whether it shows up right now
  function chapterSpecies(ch) {
    const steps = (NS.STORY.CHAPTERS[ch]?.steps || []).filter((s) => s.kind === 'route');
    const out = new Map();
    steps.forEach((step, i) => {
      if (step.wild === 0) return;
      for (const e of stepPool(ch, steps, i)) {
        const m = out.get(e.id) || { id: e.id, on: false, when: new Set() };
        if (e.on) m.on = true; else (e.when || []).forEach((w) => m.when.add(w));
        out.set(e.id, m);
      }
    });
    return [...out.values()];
  }

  // Where each wanted species can be caught, across every unlocked chapter (cached per minute)
  let spotCache = { key: '', map: new Map() };
  function spotIndex(ids, reg) {
    const adv = ADV();
    const unlocked = adv.unlocked | 0;
    let phase = '';
    try { phase = NS.DAYTIME.phase().key; } catch {}
    const key = [reg, unlocked, adv.chapter, phase, Math.floor(Date.now() / 60000), [...ids].sort((a, b) => a - b).join(',')].join('|');
    if (spotCache.key === key) return spotCache.map;
    const want = new Set(ids);
    const map = new Map();
    const CH = NS.STORY.CHAPTERS;
    for (let ch = 0; ch <= unlocked && ch < CH.length; ch++) {
      if (!CH[ch] || CH[ch].league || regionOfCh(ch) !== reg) continue;
      const steps = (CH[ch].steps || []).filter((s) => s.kind === 'route');
      steps.forEach((step, i) => {
        if (step.wild === 0) return;
        for (const e of stepPool(ch, steps, i)) {
          if (!want.has(e.id)) continue;
          const list = map.get(e.id) || [];
          let r = list.find((x) => x.ch === ch);
          if (!r) { r = { ch, on: false, pct: 0, when: new Set() }; list.push(r); map.set(e.id, list); }
          if (e.on) { r.on = true; r.pct = Math.max(r.pct, e.pct || 0); } else (e.when || []).forEach((w) => r.when.add(w));
        }
      });
    }
    spotCache = { key, map };
    return map;
  }

  function weatherAt(node, ch) {
    if (!node) return null;
    const step = (NS.STORY.CHAPTERS[ch]?.steps || []).find((s) => s.kind === 'route' && s.name === node.name);
    try {
      return NS.WEATHER.current({ ch, name: node.name, bg: node.bg, climate: step?.climate, indoor: step?.indoor, areas: node.areas });
    } catch { return null; }
  }
  const cond = (k) => { try { const c = NS.DAYTIME.cond(k); return { icon: c.icon, name: tr(c.name) }; } catch { return { icon: '', name: k }; } };
  const weatherInfo = (k) => { try { const i = NS.WEATHER.info(k); return { key: k, icon: i.icon, name: tr(i.name) }; } catch { return { key: k, ...cond(k) }; } };

  // Extra steps to play after the last target, picked once per run
  const runExtra = new WeakMap();
  const randInt = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
  function extraFor(nodes) {
    if (!runExtra.has(nodes)) runExtra.set(nodes, randInt(Math.min(extraMin, extraMax), Math.max(extraMin, extraMax)));
    return runExtra.get(nodes);
  }

  // The current run, measured against a set of target species
  function runInfo(targets) {
    const adv = ADV();
    const ch = adv.chapter;
    const nodes = Array.isArray(adv.nodes) ? adv.nodes : [];
    const cur = Math.max(0, adv.node | 0);
    const pools = nodes.map((n) => poolOfNode(n, ch));
    const hits = pools.map((p) => p.filter((e) => e.on && targets.has(e.id)).map((e) => e.id));
    let last = -1;
    hits.forEach((h, i) => { if (h.length) last = i; });
    return { adv, ch, nodes, cur, pools, hits, last, extra: extraFor(nodes) };
  }

  // ---------- Queue planning ----------
  // Queue entries are { id, reg }: the species and the region it should be caught in
  function normQueue() {
    if (!queue.some((e) => typeof e !== 'object')) return;
    const reg = curRegion();
    queue = queue.map((e) => (typeof e === 'object' ? e : { id: +e, reg }));
    saveQueue();
  }
  const isDone = (e) => regCaught(e.id, e.reg);
  const inQueue = (id, reg) => queue.some((e) => e.id === id && e.reg === reg);
  const pendingQueue = () => queue.filter((e) => !isDone(e));
  const skipUntil = new Map();   // `${id}:${ch}` -> time; set when a chapter keeps giving runs without the target
  function queuePlan() {
    const reg = curRegion();
    const pending = pendingQueue().filter((e) => e.reg === reg).map((e) => e.id);
    if (!pending.length) return { pending, idx: new Map(), pick: null };
    const idx = spotIndex(pending, reg);
    const curCh = ADV().chapter;
    for (const id of pending) {
      const spots = (idx.get(id) || []).filter((r) => r.on && !((skipUntil.get(id + ':' + r.ch) || 0) > Date.now()));
      if (!spots.length) continue;
      const best = spots.slice().sort((a, b) => b.pct - a.pct || a.ch - b.ch)[0];
      const here = spots.find((r) => r.ch === curCh);
      const ch = here && here.pct >= best.pct * 0.5 ? curCh : best.ch;   // stay put unless another chapter is much better
      return { pending, idx, pick: { id, ch } };
    }
    return { pending, idx, pick: null };
  }
  // Queued species that are catchable right now in a given chapter
  const queueTargetsIn = (plan, ch) => new Set(plan.pending.filter((id) => (plan.idx.get(id) || []).some((r) => r.ch === ch && r.on)));

  // ---------- Automatic moves ----------
  let replays = 0, emptyRuns = 0, pausedByGuard = false, status = '', queued = null, lastSwitch = 0, lastPlan = null;
  function schedule(kind, ch, stillValid) {
    if (queued) return;
    queued = setTimeout(() => {
      queued = null;
      if (!onAdventure() || !stillValid()) return;
      try {
        if (kind === 'go') NS.Screens.adventure.goChapter(ch);
        else NS.Screens.adventure.restartChapter(ch);
        replays++;
        lastSwitch = Date.now();
      } catch {}
    }, randInt(1500, 4000));
  }

  function chapterTick(m) {
    if (!auto || !m || m.special || m.adv.paused || pausedByGuard || !m.targetNow) return;
    const after = m.last + m.extra;
    if (m.cur <= after) { if (m.last >= 0) emptyRuns = 0; status = T().willReplay(after + 1); return; }
    if (!onAdventure()) { status = T().waitScreen; return; }
    const nodes = m.nodes, ch = m.ch;
    schedule('restart', ch, () => {
      const r = runInfo(picks);
      if (r.nodes !== nodes || r.ch !== ch || r.cur <= r.last + r.extra) return false;
      if (r.last === -1 && ++emptyRuns > 5) { pausedByGuard = true; status = T().paused; return false; }
      return true;
    });
  }

  function queueTick() {
    const adv = ADV();
    if (special(adv)) { status = T().special; return; }
    if (adv.capture && adv.capture.on === false) { status = T().qCaptureOff; return; }
    const plan = queuePlan();
    lastPlan = plan;
    const frontier = Math.min(adv.unlocked | 0, NS.STORY.CHAPTERS.length - 1);
    if (!plan.pick) {
      status = pendingQueue().length ? T().qIdle : T().qAllDone;
      if (adv.chapter !== frontier && regionOfCh(frontier) !== regionOfCh(adv.chapter)) { status = T().qFrontOther; return; }
      if (adv.chapter !== frontier && !NS.STORY.CHAPTERS[frontier]?.league) {
        if (!onAdventure()) { status = T().waitScreen; return; }
        if (Date.now() - lastSwitch > 15000) schedule('go', frontier, () => ADV().chapter !== frontier && !queuePlan().pick);
      }
      return;
    }
    const { id, ch } = plan.pick;
    const name = rawName(id), cname = chapterName(ch);
    if (adv.chapter !== ch) {
      // Never pull you off the newest chapter mid-run: switching chapters resets the run to step 1
      if (adv.chapter === frontier && (adv.node | 0) > 0) { status = T().qWaitFront(name); return; }
      status = T().qHunting(name, cname);
      if (!onAdventure()) { status = T().waitScreen; return; }
      if (Date.now() - lastSwitch < 15000) return;
      schedule('go', ch, () => ADV().chapter !== ch);
      return;
    }
    // In the right chapter: replay after the last step that still has something from the queue
    const targets = queueTargetsIn(plan, ch);
    const r = runInfo(targets);
    const after = r.last + r.extra;
    status = T().qHunting(name, cname);
    if (r.cur <= after) { if (r.last >= 0) emptyRuns = 0; return; }
    if (!onAdventure()) { status = T().waitScreen; return; }
    const nodes = r.nodes;
    schedule('restart', ch, () => {
      const a = ADV();
      if (a.nodes !== nodes || a.chapter !== ch) return false;
      const rr = runInfo(targets);
      if (rr.cur <= rr.last + rr.extra) return false;
      if (rr.last === -1 && ++emptyRuns > 5) { skipUntil.set(id + ':' + ch, Date.now() + 10 * 60000); emptyRuns = 0; return false; }
      return true;
    });
  }

  // ---------- Catch watcher ----------
  // The game fires no catch event, so watch the save: a species counts as caught when
  // more of it shows up in the box, or it gets newly registered in the Pokédex.
  let notice = '', noticeAt = 0, toastEl = null, titleBefore = null;
  const catchBase = new Map();
  function countOf(S, id) { let n = 0; for (const mm of S.mons) if (mm && mm.id === id) n++; return n; }
  function checkCatch() {
    const S = NS?.Game?.S;
    if (!S || !Array.isArray(S.mons) || !ADV()) return;
    normQueue();
    const here = curRegion();
    const watch = new Map();
    if (!qauto) for (const id of picks) watch.set(id + ':' + here, { id, reg: here, queued: false });   // chapter picks only matter outside queue mode
    for (const e of queue) watch.set(e.id + ':' + e.reg, { ...e, queued: true });
    for (const [k, w] of watch) {
      const now = { n: countOf(S, w.id), dex: regCaught(w.id, w.reg) };
      const prev = catchBase.get(k);
      catchBase.set(k, now);
      if (prev && ((now.dex && !prev.dex) || (w.reg === here && now.n > prev.n))) onCaught(w.id, w.queued);
    }
    for (const k of [...catchBase.keys()]) if (!watch.has(k)) catchBase.delete(k);
  }
  function onCaught(id, isQueued) {
    let msg;
    if (isQueued) {
      const left = pendingQueue().length;
      msg = left ? T().qGot(rawName(id), left) : T().qGotAll(rawName(id));
      spotCache.key = '';
    } else {
      msg = T().got(rawName(id));
      if (auto) { auto = false; store.set('auto', false); }
      if (queued) { clearTimeout(queued); queued = null; }
    }
    notice = msg;
    noticeAt = Date.now();
    showToast(msg);
    if (document.hidden) {
      if (titleBefore == null) titleBefore = document.title;
      document.title = '★ ' + msg;
    }
    syncControls();
    render(true);
  }
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden && titleBefore != null) { document.title = titleBefore; titleBefore = null; }
  });
  function showToast(msg) {
    if (!toastEl) {
      toastEl = document.createElement('div');
      toastEl.id = 'cc-toast';
      toastEl.setAttribute('role', 'status');
      document.body.appendChild(toastEl);
    }
    toastEl.textContent = msg;
    toastEl.classList.add('cc-show');
    clearTimeout(showToast.t);
    showToast.t = setTimeout(() => toastEl.classList.remove('cc-show'), 8000);
  }

  // ---------- Background mode ----------
  // While the tab is hidden the game pauses its live loop and simulates the time away when you come back,
  // so nothing can replay at the right step. Before the tab hides, point the game's own chapter loop (the ↻
  // button on the map) at the chapter being hunted, and put your loops back once the catch-up has run.
  const LOOP_KEY = 'loopsBackup';
  function huntingChapter() {
    const adv = ADV();
    if (!adv || special(adv)) return null;
    let ch = null;
    if (qauto) { const plan = queuePlan(); if (plan.pick && plan.pick.ch === adv.chapter) ch = adv.chapter; }
    else if (auto && picks.size && chapterSpecies(adv.chapter).some((x) => x.on && picks.has(x.id))) ch = adv.chapter;
    return ch != null && ch !== (adv.unlocked | 0) ? ch : null;
  }
  function setLoops(list) {
    const A = NS.Adventure;
    for (const c of [...(ADV().loops || [])]) if (!list.includes(c)) A.toggleLoop(c);
    for (const c of list) if (!A.isLooping(c)) A.toggleLoop(c);
    try { NS.Game.save(); } catch {}
  }
  function onHide() {
    if (!NS || !ADV() || store.get(LOOP_KEY, null)) return;
    let ch = null;
    try { ch = huntingChapter(); } catch {}
    if (ch == null) return;
    try { store.set(LOOP_KEY, [...(ADV().loops || [])]); setLoops([ch]); } catch {}
  }
  let restoring = false;
  async function restoreLoops() {
    const backup = store.get(LOOP_KEY, null);
    if (!backup || restoring || !NS || !ADV()) return;
    restoring = true;
    await new Promise((r) => setTimeout(r, 1500));
    for (let i = 0; i < 1200; i++) {   // wait for the game's catch-up to finish first
      if (document.hidden) { restoring = false; return; }
      const C = NS.CatchUp;
      if (!C || !(C.held || C.pending || C.busy)) break;
      await new Promise((r) => setTimeout(r, 500));
    }
    try { setLoops(backup); localStorage.removeItem('cc-' + LOOP_KEY); } catch {}
    restoring = false;
    tick(true);
  }
  document.addEventListener('visibilitychange', () => { if (document.hidden) onHide(); else restoreLoops(); });

  // ---------- Pokémon names, read from the game's own language packs ----------
  const NAME_LANG = { zh: 'zh-Hans', en: 'en' };
  const nameDict = {}, loading = {};
  function loadNames(l) {
    const key = NAME_LANG[l];
    const live = window.I18N_DATA?.[key]?.pokemon;
    if (live) {
      if (!nameDict[l]) { const d = {}; for (const k in live) d[k] = live[k][0]; nameDict[l] = d; }
      return Promise.resolve();
    }
    try {
      const c = JSON.parse(localStorage.getItem('eggq-names-' + key) || 'null');
      if (c && Object.keys(c).length > 100) { nameDict[l] = c; return Promise.resolve(); }
    } catch {}
    if (loading[l]) return loading[l];
    const srcs = [...document.scripts].map((s) => s.src);
    const boot = srcs.find((s) => /boot\.js/.test(s));
    const app = srcs.find((s) => /bundle\/app\./.test(s));
    if (!boot || !app) return Promise.resolve();   // game bundles not on the page yet; a later render tries again
    return (loading[l] = (async () => {
      const bt = await fetch(boot).then((r) => r.text());
      const file = (bt.match(new RegExp(`lang-${key.replace('-', '\\-')}\\.[0-9a-f]+\\.js`)) || [])[0];
      if (!file) return;
      const txt = await fetch(app.replace(/app\.[^/]+$/, file)).then((r) => r.text());
      const out = {};
      const st = txt.indexOf('pokemon:{');
      if (st < 0) return;
      const re = /(\d+):\["((?:[^"\\]|\\.)*)"/g;
      re.lastIndex = st;
      let mm, lastI = st;
      while ((mm = re.exec(txt))) {
        if (mm.index - lastI > 3000) break;
        try { out[mm[1]] = JSON.parse(`"${mm[2]}"`); } catch {}
        lastI = mm.index;
      }
      localStorage.setItem('eggq-names-' + key, JSON.stringify(out));
      nameDict[l] = out;
    })().catch(() => {}));
  }
  const baseId = (id) => (id >= 10000 ? Math.floor(id / 100) : id);
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const rawName = (id) => { const d = nameDict[lang]; return (d && (d[id] || d[baseId(id)])) || `#${id}`; };
  const nameOf = (id) => esc(rawName(id));

  // ---------- Static sprites: trim transparent padding so they render larger ----------
  const sprites = new Map(), spriteJobs = new Map();
  function crop(src) {
    if (spriteJobs.has(src)) return spriteJobs.get(src);
    const job = new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        try {
          const w = img.naturalWidth, h = img.naturalHeight;
          const c = document.createElement('canvas');
          c.width = w; c.height = h;
          const ctx = c.getContext('2d');
          ctx.drawImage(img, 0, 0);
          const d = ctx.getImageData(0, 0, w, h).data;
          let x0 = w, y0 = h, x1 = -1, y1 = -1;
          for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
            if (d[(y * w + x) * 4 + 3] > 8) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
          }
          if (x1 < 0) return resolve({ url: src, w, h });
          const o = document.createElement('canvas');
          o.width = x1 - x0 + 1; o.height = y1 - y0 + 1;
          o.getContext('2d').drawImage(c, x0, y0, o.width, o.height, 0, 0, o.width, o.height);
          resolve({ url: o.toDataURL(), w: o.width, h: o.height });
        } catch { resolve({ url: src, w: img.naturalWidth, h: img.naturalHeight }); }
      };
      img.onerror = () => resolve(null);
      img.src = src;
    }).then((s) => { if (s) sprites.set(src, s); return s; });
    spriteJobs.set(src, job);
    return job;
  }
  function paint(img, s) {
    if (!s) { img.style.visibility = 'hidden'; return; }
    const bw = +img.dataset.w || 30, bh = +img.dataset.h || 26;
    const k = Math.min(bw / s.w, bh / s.h);
    img.src = s.url;
    img.style.width = Math.round(s.w * k) + 'px';
    img.style.height = Math.round(s.h * k) + 'px';
  }
  function hydrate(root) {
    root.querySelectorAll('img[data-spr]').forEach((img) => {
      const src = img.dataset.spr;
