  // ---------- Rendering ----------
  const monCell = (s, targets) => {
    const tgt = targets.has(s.id), got = caughtHere(s.id);
    const w = !s.on && s.when.size ? [...s.when].map((k) => cond(k).icon).join('') : '';
    const tip = `${nameOf(s.id)} · ${got ? T().caught : T().uncaught}${w ? ' · ' + [...s.when].map((k) => cond(k).name).join(' / ') : ''}${tgt ? ' · ' + T().target : ''}`;
    return `<button class="cc-mon${tgt ? ' cc-tgt' : ''}${got ? ' cc-got' : ' cc-new'}" data-id="${s.id}" title="${esc(tip)}">${spr(s.id)}${w ? `<span class="cc-w">${w}</span>` : ''}</button>`;
  };

  function chapterHTML() {
    const t = T();
    const adv = ADV();
    if (special(adv)) return `<div class="cc-sec cc-empty">${t.special}</div>`;
    const ch = adv.chapter;
    const species = chapterSpecies(ch);
    // In queue mode the route shows what the queue is after here; otherwise your own picks
    const targets = qauto ? queueTargetsIn(lastPlan || queuePlan(), ch) : picks;
    const r = runInfo(targets);
    const targetNow = species.some((s) => s.on && targets.has(s.id));
    let phase = null;
    try { const p = NS.DAYTIME.phase(); phase = { icon: p.icon, name: tr(p.name) }; } catch {}
    const wKey = weatherAt(r.nodes[r.cur], ch);
    let indoor = false;
    try { indoor = !!NS.DAYTIME.indoorNode(r.nodes[r.cur]); } catch {}
    const weather = wKey ? weatherInfo(wKey) : null;

    const now = species.filter((s) => s.on), off = species.filter((s) => !s.on);
    const where = `<div class="cc-sec"><div class="cc-where"><span class="cc-ch">${esc(chapterName(ch))}</span><span class="cc-stepn">${t.step(r.cur + 1, r.nodes.length)}</span></div>
<div class="cc-cond">${phase ? `<span>${phase.icon} ${esc(phase.name)}</span>` : ''}<span>${weather ? `${weather.icon} ${esc(weather.name)}` : indoor ? t.indoor : t.clear}</span></div></div>`;
    const mons = `<div class="cc-sec"><div class="cc-mons">${now.map((s) => monCell(s, targets)).join('')}</div>
${off.length ? `<div class="cc-mons cc-off" title="${esc(t.other)}">${off.map((s) => monCell(s, targets)).join('')}</div>` : ''}</div>`;

    const end = (qauto || auto) && targetNow ? r.last + r.extra : -2;
    const cells = r.nodes.map((n, i) => {
      const catchable = CATCH_TYPES.has(n.type) && r.pools[i].some((e) => e.on);
      const hit = r.hits[i].length > 0;
      const cls = `cc-n${catchable ? ' cc-catch' : ''}${hit ? ' cc-hit' : ''}${i < r.cur ? ' cc-past' : ''}${i === r.cur ? ' cc-cur' : ''}${i === end ? ' cc-end' : ''}`;
      const tip = `${i + 1} · ${tr(n.name || '')} · ${t.types[n.type] || n.type}${hit ? ' · ' + r.hits[i].map(nameOf).join(', ') : ''}${i === end ? ' · ' + t.replayAt : ''}`;
      return `<span class="${cls}" title="${esc(tip)}">${i + 1}</span>`;
    }).join('');
    let sum;
    if (!targets.size) sum = t.noPicks;
    else if (!targetNow) sum = t.noneChapter;
    else if (r.last < r.cur) sum = t.noneAhead;
    else if (r.last === r.cur) sum = `<b>${t.lastHere}</b>`;
    else sum = `<b>${t.last(r.last + 1, r.last - r.cur)}</b>`;
    const route = `<div class="cc-sec"><div class="cc-route">${cells}</div><div class="cc-sum">${sum}</div></div>`;
    return where + mons + route;
  }

  function queueHTML() {
    const t = T();
    normQueue();
    if (!queue.length) return `<div class="cc-sec cc-empty">${t.qEmpty}</div>`;
    const plan = queuePlan();
    const here = curRegion();
    const active = qauto && plan.pick ? plan.pick.id : null;
    const rows = queue.map((e, qi) => {
      const id = e.id;
      let line, cls = '', tip = `${regionName(e.reg)} · ${t.drag}`;
      if (isDone(e)) { line = '<small>✓</small>'; cls = ' cc-done'; tip = `${regionName(e.reg)} · ${t.qDone}`; }
      else if (e.reg !== here) { line = `<small>${esc(regionName(e.reg))}</small>`; tip = t.qOtherReg(regionName(e.reg)); }
      else {
        const spots = plan.idx.get(id) || [];
        const on = spots.filter((r) => r.on).sort((a, b) => b.pct - a.pct);
        if (id === active) { line = `<small class="cc-hunt">▶ ${esc(chapterName(plan.pick.ch))}</small>`; cls = ' cc-active'; tip = t.qActive(chapterName(plan.pick.ch)); }
        else if (on.length) { line = `<small class="cc-ok">${esc(chapterName(on[0].ch))}</small>`; tip = t.qNow(chapterName(on[0].ch)); }
        else if (spots.length) {
          const sp = spots[0];
          line = `<small>${[...sp.when].map((k) => cond(k).icon).join('')} ${esc(chapterName(sp.ch))}</small>`;
          tip = t.qNeed([...sp.when].map((k) => cond(k).name).join(' / '), chapterName(sp.ch));
        } else { line = '<small>—</small>'; tip = t.qNowhere; }
      }
      return `<li class="cc-qi${cls}" draggable="true" data-qi="${qi}" title="${esc(tip)}"><span class="cc-grip">⋮⋮</span><span class="cc-sp">${spr(id, 30, 28)}</span>
<span class="cc-qn"><b>${nameOf(id)}</b>${line}</span><button class="cc-qx" data-qdel="${qi}" aria-label="remove">✕</button></li>`;
    }).join('');
    const doneCount = queue.filter(isDone).length;
    return `<div class="cc-sec"><ol class="cc-q">${rows}</ol>${doneCount ? `<div class="cc-acts cc-end"><button data-act="cleardone">${t.qClearDone}</button></div>` : ''}</div>`;
  }

  let lastHtml = '';
  function render(force) {
    if (!panel) return;
    const t = T();
    panel.querySelector('.cc-title').textContent = t.title;
    panel.querySelectorAll('[data-l]').forEach((b) => b.classList.toggle('cc-sel', b.dataset.l === lang));
    panel.querySelectorAll('[data-tab]').forEach((b) => b.classList.toggle('cc-sel', b.dataset.tab === tab));
    panel.querySelectorAll('[data-t]').forEach((el) => { el.textContent = t[el.dataset.t]; });
    panel.querySelectorAll('[data-for]').forEach((el) => { el.hidden = el.dataset.for !== tab; });
    if (qauto) els.autoRow.hidden = true;
    searchEl.placeholder = t.qSearch;
    els.extra.style.opacity = auto || qauto ? '1' : '.5';
    const fresh = notice && Date.now() - noticeAt < 20000;
    statEl.textContent = (fresh && notice) || status || (replays ? t.restarted(replays) : '');
    statEl.classList.toggle('cc-gold', !!fresh);
    syncControls();
    if (!panel.classList.contains('cc-open') || dragging != null) return;
    if (!nameDict[lang]) loadNames(lang).then(() => { if (nameDict[lang]) render(true); });

    let html;
    if (!NS) html = `<div class="cc-sec cc-empty">${document.readyState === 'complete' ? t.noHook : t.loading}</div>`;
    else if (!ADV() || !NS.STORY?.CHAPTERS) html = `<div class="cc-sec cc-empty">${t.loading}</div>`;
    else html = tab === 'queue' ? queueHTML() : chapterHTML();
    if (force || html !== lastHtml) { body.innerHTML = html; lastHtml = html; hydrate(body); }
  }

  function tick(force) {
    status = '';
    if (NS && ADV() && NS.STORY?.CHAPTERS) {
      normQueue();
      if (!document.hidden && !restoring && store.get(LOOP_KEY, null)) restoreLoops();
      if (restoring) { render(force === true); return; }
      try {
        if (qauto) queueTick();
        else if (auto) {
          const adv = ADV();
          const species = special(adv) ? [] : chapterSpecies(adv.chapter);
          const r = runInfo(picks);
          chapterTick({ ...r, special: special(adv), targetNow: species.some((s) => s.on && picks.has(s.id)) });
        }
      } catch (err) { /* keep the panel alive if the game changes shape */ }
    }
    render(force === true);
  }

  const start = () => {
    mountUI();
    tick(true);
    setInterval(tick, 2000);
    setInterval(() => { if (NS) checkCatch(); }, 700);
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true });
  else start();
})();

