    const eggs = Array.isArray(p.eggs) ? p.eggs : [];
    const me = `${s.trainer?.since ?? ''}:${s.trainer?.id ?? ''}`;
    const ranges = ['kanto', ...(s.travel?.to || []), s.link?.to].map((k) => REGIONS[k]).filter(Boolean);
    return {
      eggs,
      roll: (k, slot = 0) => hash01(`${me}|egg|${k}|${slot}`),
      next: Number.isFinite(p.laid) ? p.laid : (+s.stats?.hatched || 0) + eggs.length,
      parents: (p.mons || []).map((x) => x && x.mon).filter((m) => m && canLay(m)),
      charges: +p.bx || 0,
      isOpen: (id) => { const n = baseId(id); return ranges.some(([a, b]) => n >= a && n <= b); },
    };
  }
  const parentAt = (st, k) => (st.parents.length ? st.parents[Math.floor(st.roll(k, 1) * st.parents.length)] : null);
  function speciesOf(st, pid) {
    if (LAYS[pid] != null) return LAYS[pid];
    if (FORM_EGG[pid] != null) return FORM_EGG[pid];
    let k = baseId(pid);
    while (FROM[k] && st.isOpen(FROM[k])) k = FROM[k];
    return k;
  }
  function willBeShiny(st, k) {
    const p = parentAt(st, k);
    if (!p) return false;
    return st.roll(k) < (p.shiny ? PARENT : BASE) * (k - st.next < st.charges ? BERRY : 1);
  }
  function eggShiny(st, e) {
    if ('shiny' in e) return !!e.shiny;
    const v = Number.isInteger(e.k) ? st.roll(e.k) : hash01(String(e.uid ?? e.laidAt));
    return v < Math.max(e.sp ? (+e.sp === 2 ? PARENT : PARENT_OLD) : 0, BASE) * (e.bx ? BERRY : 1);
  }
  function findNext(st, test, n = 1, from = st.next, limit = 30000) {
    const out = [];
    for (let k = from; out.length < n && k < from + limit; k++) if (test(k)) out.push(k);
    return out;
  }

  // ---------- Pokémon names, read from the game's own language packs ----------
  const NAME_LANG = { zh: 'zh-Hans', en: 'en' };
  const names = {};
  const loading = {};
  function loadNames(lang) {
    const key = NAME_LANG[lang];
    const live = window.I18N_DATA?.[key]?.pokemon;
    if (live) { names[lang] = (id) => (live[id] || [])[0]; return Promise.resolve(); }
    try {
      const c = JSON.parse(localStorage.getItem('eggq-names-' + key) || 'null');
      if (c && Object.keys(c).length > 100) { names[lang] = (id) => c[id]; return Promise.resolve(); }
    } catch {}
    if (loading[lang]) return loading[lang];
    return (loading[lang] = (async () => {
      const srcs = [...document.scripts].map((s) => s.src);
      const boot = srcs.find((s) => /boot\.js/.test(s));
      const app = srcs.find((s) => /bundle\/app\./.test(s));
      if (!boot || !app) return;
      const bt = await fetch(boot).then((r) => r.text());
      const file = (bt.match(new RegExp(`lang-${key.replace('-', '\\-')}\\.[0-9a-f]+\\.js`)) || [])[0];
      if (!file) return;
      const txt = await fetch(app.replace(/app\.[^/]+$/, file)).then((r) => r.text());
      const out = {};
      const st = txt.indexOf('pokemon:{');
      if (st < 0) return;
      const re = /(\d+):\["((?:[^"\\]|\\.)*)"/g;
      re.lastIndex = st;
      let m, last = st;
      while ((m = re.exec(txt))) {
        if (m.index - last > 3000) break;
        try { out[m[1]] = JSON.parse(`"${m[2]}"`); } catch {}
        last = m.index;
      }
      localStorage.setItem('eggq-names-' + key, JSON.stringify(out));
      names[lang] = (id) => out[id];
    })().catch(() => {}));
  }

  // ---------- Static sprites: trim transparent padding so they render larger ----------
  const sprites = new Map();   // src -> { url, w, h }
  const pending = new Map();
  const BOX_W = 40, BOX_H = 32;
  function crop(src) {
    if (pending.has(src)) return pending.get(src);
    const job = new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        try {
          const w = img.naturalWidth, h = img.naturalHeight;
          const c = document.createElement('canvas');
          c.width = w; c.height = h;
          const ctx = c.getContext('2d');
          ctx.drawImage(img, 0, 0);
          const d = ctx.getImageData(0, 0, w, h).data;
          let x0 = w, y0 = h, x1 = -1, y1 = -1;
          for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
            if (d[(y * w + x) * 4 + 3] > 8) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
          }
          if (x1 < 0) return resolve({ url: src, w, h });
          const o = document.createElement('canvas');
          o.width = x1 - x0 + 1; o.height = y1 - y0 + 1;
          o.getContext('2d').drawImage(c, x0, y0, o.width, o.height, 0, 0, o.width, o.height);
          resolve({ url: o.toDataURL(), w: o.width, h: o.height });
        } catch { resolve({ url: src, w: img.naturalWidth, h: img.naturalHeight }); }
      };
      img.onerror = () => resolve(null);
      img.src = src;
    }).then((s) => { if (s) sprites.set(src, s); return s; });
    pending.set(src, job);
    return job;
  }
  function paint(img, s) {
    if (!s) { img.style.visibility = 'hidden'; return; }
    const k = Math.min(BOX_W / s.w, BOX_H / s.h);
    img.src = s.url;
    img.style.width = Math.round(s.w * k) + 'px';
    img.style.height = Math.round(s.h * k) + 'px';
  }
  function hydrate(root) {
    root.querySelectorAll('img[data-spr]').forEach((img) => {
      const src = img.dataset.spr;
      if (sprites.has(src)) paint(img, sprites.get(src));
      else crop(src).then((s) => paint(img, s));
    });
  }

  // ---------- UI ----------
  let lang = localStorage.getItem('eggq-lang') || (/^zh/.test(localStorage.getItem('pokecatch.lang') || navigator.language) ? 'zh' : 'en');
  const T = () => TEXT[lang];
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const nameOf = (id) => esc((names[lang] && (names[lang](id) || names[lang](baseId(id)))) || `#${id}`);
  const spr = (id, shiny) => `<span class="eq-spr"><img data-spr="assets/pokemon/${shiny ? 'shiny/' : ''}${id}.png" alt=""></span>`;
  const status = (sh) => (sh ? `<span class="eq-st eq-y"><img src="${ICON.sparkle}" alt="">${T().shiny}</span>` : `<span class="eq-st">${T().normal}</span>`);
  const fmt = (ms) => { const m = Math.ceil(ms / 60000); return `${Math.floor(m / 60)}:${String(m % 60).padStart(2, '0')}`; };

  const style = document.createElement('style');
  style.textContent = `
#eq-btn{position:fixed;right:18px;bottom:18px;z-index:99998;width:48px;height:48px;padding:0;border-radius:10px;border:1px solid #333a52;background:#1c2030;cursor:pointer;display:grid;place-items:center;box-shadow:0 4px 12px rgba(0,0,0,.4)}
#eq-btn:hover{border-color:#f4c430}
#eq-btn:focus-visible{outline:2px solid #f4c430;outline-offset:2px}
#eq-btn>img{width:34px;height:34px;image-rendering:pixelated}
#eq-btn.eq-has::after{content:"";position:absolute;top:-7px;right:-7px;width:18px;height:18px;background:url(assets/ui/sparkle.svg) center/contain no-repeat}
#eq-panel{position:fixed;right:18px;bottom:76px;z-index:99999;width:344px;max-height:calc(100vh - 96px);overflow:auto;display:none;background:#141826;color:#eef1f8;border:1px solid #333a52;border-radius:12px;box-shadow:0 12px 32px rgba(0,0,0,.5);font:13px/1.4 system-ui,"PingFang SC","Microsoft YaHei",sans-serif;text-align:left}
#eq-panel.eq-open{display:block}
#eq-panel *{box-sizing:border-box}
#eq-panel img{image-rendering:pixelated}
#eq-panel button:focus-visible{outline:2px solid #f4c430;outline-offset:1px}
#eq-panel .eq-head{display:flex;align-items:center;gap:8px;height:38px;padding:0 6px 0 10px;border-bottom:1px solid #333a52;cursor:move;user-select:none}
#eq-panel .eq-head>img{width:22px;height:22px}
#eq-panel .eq-title{flex:1;font:600 13px/1 system-ui,"PingFang SC","Microsoft YaHei",sans-serif;color:#c3c9d8;letter-spacing:.5px}
#eq-panel .eq-head button{background:none;border:0;color:#9aa3bb;font:600 12px/1 system-ui;padding:6px 5px;cursor:pointer}
#eq-panel .eq-head button.eq-on{color:#eef1f8;box-shadow:inset 0 -2px 0 #f4c430}
#eq-panel .eq-head .eq-x{font-size:15px;margin-left:2px}
#eq-panel .eq-sec{padding:8px 10px;border-bottom:1px solid #252a3d}
#eq-panel .eq-sec:last-child{border-bottom:0}
#eq-panel .eq-label{display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#9aa3bb;margin-bottom:2px}
#eq-panel .eq-label img{width:11px;height:11px;margin-right:3px;vertical-align:-1px}
#eq-panel .eq-row{display:grid;align-items:center;column-gap:8px;min-height:36px}
#eq-panel .eq-inc{grid-template-columns:40px minmax(0,1fr) auto 38px;position:relative}
#eq-panel .eq-prog{position:absolute;left:48px;right:0;bottom:2px;height:2px;background:#252a3d;border-radius:1px}
#eq-panel .eq-prog i{display:block;height:100%;background:#6b7594;border-radius:1px}
#eq-panel .eq-nx{grid-template-columns:62px 34px 40px minmax(0,1fr) auto}
#eq-panel .eq-spr{width:40px;height:32px;display:flex;align-items:center;justify-content:center;overflow:hidden}
#eq-panel .eq-spr img{max-width:none;max-height:none;flex:none}
#eq-panel .eq-k{font:18px/1 "Jersey 10",system-ui;color:#9aa3bb;margin-right:5px}
#eq-panel .eq-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:600}
#eq-panel .eq-sub{display:block;font-size:11px;font-weight:400;color:#9aa3bb}
#eq-panel .eq-st{display:inline-flex;align-items:center;gap:3px;font-size:12px;color:#9aa3bb;white-space:nowrap}
#eq-panel .eq-st.eq-y{color:#f4c430;font-weight:700}
#eq-panel .eq-st img{width:12px;height:12px}
#eq-panel .eq-time{font:17px/1 "Jersey 10",system-ui;color:#c3c9d8;text-align:right}
#eq-panel .eq-lab{font-size:12px;color:#9aa3bb;white-space:nowrap}
#eq-panel .eq-n{font:22px/1 "Jersey 10",system-ui}
#eq-panel .eq-gold .eq-n{color:#f4c430}
#eq-panel .eq-empty{font-size:12px;color:#9aa3bb;padding:6px 0}
#eq-panel .eq-grid{display:grid;grid-template-columns:repeat(15,1fr);gap:2px;margin-top:4px}
#eq-panel .eq-c{position:relative;height:19px;display:grid;place-items:center;border-radius:3px;background:#1c2030;color:#5b6482;font:14px/1 "Jersey 10",system-ui}
#eq-panel .eq-t0,#eq-panel .eq-sw0{background:#f4c430}
#eq-panel .eq-t1,#eq-panel .eq-sw1{background:#8b7be8}
#eq-panel .eq-t2,#eq-panel .eq-sw2{background:#45c4d9}
#eq-panel .eq-t3,#eq-panel .eq-sw3{background:linear-gradient(135deg,#8b7be8 50%,#45c4d9 50%)}
#eq-panel .eq-c.eq-t0,#eq-panel .eq-c.eq-t1,#eq-panel .eq-c.eq-t2,#eq-panel .eq-c.eq-t3{color:#141826}
#eq-panel .eq-c.eq-cur{outline:1px solid #eef1f8;outline-offset:1px}
#eq-panel .eq-c.eq-now::after{content:"";position:absolute;top:-5px;right:-4px;width:11px;height:11px;background:url(assets/ui/sparkle.svg) center/contain no-repeat}
#eq-panel .eq-key{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px}
#eq-panel .eq-tile{min-width:0}
#eq-panel .eq-tn{display:flex;align-items:center;gap:4px;font-size:12px;color:#c3c9d8;white-space:nowrap}
#eq-panel .eq-sw{width:9px;height:9px;border-radius:2px;flex:none}
#eq-panel .eq-big{display:block;font:24px/1.1 "Jersey 10",system-ui;margin-top:2px}
#eq-panel .eq-more{display:block;font:15px/1 "Jersey 10",system-ui;color:#9aa3bb;word-spacing:3px}
`;
  document.head.appendChild(style);

  const btn = document.createElement('button');
  btn.id = 'eq-btn';
  btn.innerHTML = `<img src="${ICON.egg}" alt="">`;
  const panel = document.createElement('div');
  panel.id = 'eq-panel';
  panel.innerHTML = `<div class="eq-head"><img src="${ICON.egg}" alt=""><span class="eq-title"></span>
<button data-l="zh">中</button><button data-l="en">EN</button><button class="eq-x" data-x aria-label="close">✕</button></div>
<div class="eq-body"></div>`;
  document.body.append(btn, panel);
  const body = panel.querySelector('.eq-body');

  const OPEN_KEY = 'eggq-open', POS_KEY = 'eggq-pos3';
  // Keep a dragged panel inside the window (it can end up off-screen after the window shrinks)
  const keepOnScreen = () => {
    if (!panel.style.left) return;
    const w = panel.offsetWidth || 344, h = panel.offsetHeight || 200;
    const x = Math.max(0, Math.min(innerWidth - w, parseFloat(panel.style.left) || 0));
    const y = Math.max(0, Math.min(innerHeight - Math.min(h, 120), parseFloat(panel.style.top) || 0));
    Object.assign(panel.style, { left: x + 'px', top: y + 'px' });
  };
  // Whichever Poke'Catch panel was used last sits on top
  const toFront = () => { window.__pcZ = (window.__pcZ || 100000) + 1; panel.style.zIndex = window.__pcZ; };
  addEventListener('resize', keepOnScreen);
  panel.addEventListener('mousedown', toFront);
  const setOpen = (on) => {
    panel.classList.toggle('eq-open', on);
    localStorage.setItem(OPEN_KEY, on ? '1' : '0');
    if (on) { toFront(); render(true); keepOnScreen(); }
  };
  btn.onclick = () => setOpen(!panel.classList.contains('eq-open'));
  panel.querySelector('[data-x]').onclick = () => setOpen(false);
  panel.querySelectorAll('[data-l]').forEach((b) => (b.onclick = () => {
    lang = b.dataset.l;
    localStorage.setItem('eggq-lang', lang);
    render(true);
    loadNames(lang).then(() => render(true));
  }));

  try {
    const pos = JSON.parse(localStorage.getItem(POS_KEY) || 'null');
    if (pos) Object.assign(panel.style, { left: pos.x + 'px', top: pos.y + 'px', right: 'auto', bottom: 'auto' });
  } catch {}
  panel.querySelector('.eq-head').addEventListener('mousedown', (e) => {
    if (e.target.closest('button')) return;
    const r = panel.getBoundingClientRect(), dx = e.clientX - r.left, dy = e.clientY - r.top;
    const move = (ev) => Object.assign(panel.style, {
      left: Math.max(0, Math.min(innerWidth - 80, ev.clientX - dx)) + 'px',
      top: Math.max(0, Math.min(innerHeight - 40, ev.clientY - dy)) + 'px', right: 'auto', bottom: 'auto',
    });
    const up = () => {
      removeEventListener('mousemove', move); removeEventListener('mouseup', up);
      const r2 = panel.getBoundingClientRect();
      localStorage.setItem(POS_KEY, JSON.stringify({ x: r2.left, y: r2.top }));
    };
    addEventListener('mousemove', move); addEventListener('mouseup', up);
    e.preventDefault();
  });

  function nextRow(label, k, sp, sh, sub) {
    return `<div class="eq-row eq-nx${sh ? ' eq-gold' : ''}"><span class="eq-lab">${label}</span><span class="eq-n">#${k}</span>${spr(sp, sh)}
<span class="eq-name">${nameOf(sp)}${sub ? `<span class="eq-sub">${sub}</span>` : ''}</span>${status(sh)}</div>`;
  }

  let lastHtml = '';
  function render(force) {
    const st = read();
    btn.classList.toggle('eq-has', !!st && st.eggs.some((e) => eggShiny(st, e)));
    if (!panel.classList.contains('eq-open')) return;
    const t = T();
    panel.querySelector('.eq-title').textContent = t.title;
    panel.querySelectorAll('[data-l]').forEach((b) => b.classList.toggle('eq-on', b.dataset.l === lang));
    if (!names[lang]) loadNames(lang).then(() => render(true));

    let html;
    if (!st) html = `<div class="eq-sec eq-empty">${t.noSave}</div>`;
    else {
      const now = Date.now();

      // Incubator
      const inc = st.eggs.length ? st.eggs.map((e) => {
        const sh = eggShiny(st, e);
        const span = (+e.hatchAt || 0) - (+e.laidAt || 0), left = (+e.hatchAt || 0) - now;
        const pct = span > 0 ? Math.max(0, Math.min(100, Math.round((1 - left / span) * 100))) : 100;
        return `<div class="eq-row eq-inc${sh ? ' eq-gold' : ''}">${spr(e.id, sh)}
<span class="eq-name"><span class="eq-k">#${e.k ?? '?'}</span>${nameOf(e.id)}</span>${status(sh)}
<span class="eq-time">${left <= 0 ? t.ready : fmt(left)}</span><span class="eq-prog"><i style="width:${pct}%"></i></span></div>`;
      }).join('') : `<div class="eq-empty">${t.empty}</div>`;

      // Next egg / next shiny
      let nx;
      const p0 = parentAt(st, st.next);
      if (!p0) nx = `<div class="eq-empty">${t.noParent}</div>`;
      else {
        const sh0 = willBeShiny(st, st.next);
        nx = nextRow(t.next, st.next, speciesOf(st, p0.id), sh0, `${t.parent} ${nameOf(p0.id)}`);
        const ks = findNext(st, (k) => willBeShiny(st, k), 1, st.next + 1)[0];
        nx += ks
          ? nextRow(sh0 ? t.afterShiny : t.nextShiny, ks, speciesOf(st, parentAt(st, ks).id), true, t.away(ks - st.next + 1))
          : `<div class="eq-empty">${t.nextShiny}: ${t.never}</div>`;
      }

      // Upcoming egg numbers
      let cells = '';
      for (let k = st.next; k < st.next + GRID; k++) {
        const ti = tierOf(st.roll(k)), pk = parentAt(st, k);
        const tip = `#${k}${pk ? ' ' + nameOf(speciesOf(st, pk.id)) : ''}${ti < 4 ? ', ' + t.tiers[ti] : ''}`;
        cells += `<span class="eq-c${ti < 4 ? ' eq-t' + ti : ''}${k === st.next ? ' eq-cur' : ''}${willBeShiny(st, k) ? ' eq-now' : ''}" title="${tip}">${k}</span>`;
      }
      const key = [0, 1, 2, 3].map((i) => {
        const ks = findNext(st, (k) => tierOf(st.roll(k)) === i, 3);
        return `<div class="eq-tile" title="${t.tips[i]}"><span class="eq-tn"><span class="eq-sw eq-sw${i}"></span>${t.tiers[i]}</span>
<span class="eq-big">${ks.length ? '#' + ks[0] : '—'}</span><span class="eq-more">${ks.slice(1).join(' ')}</span></div>`;
      }).join('');

      html = `<div class="eq-sec"><div class="eq-label">${t.incubator}</div>${inc}</div>
<div class="eq-sec">${nx}</div>
<div class="eq-sec"><div class="eq-label"><span>${t.grid}</span><span><img src="${ICON.sparkle}" alt="">${t.now}</span></div>
<div class="eq-grid">${cells}</div><div class="eq-key">${key}</div></div>`;
    }
    if (force || html !== lastHtml) { body.innerHTML = html; lastHtml = html; hydrate(body); }
  }

  setInterval(() => render(false), 3000);
  loadNames(lang);
  if (localStorage.getItem(OPEN_KEY) === '1') setOpen(true); else render(false);
})();

