(function () {
  'use strict';

  // =====================================================================
  // YOUTUBE API KEY
  // Easiest: leave this line alone and paste your key into the field that
  // shows up in the Videos section on any Deku Deals game page. Tampermonkey
  // keeps it there, and updates from GitHub won't touch it.
  // Or replace PASTE_API_KEY_HERE with your key (keep the quotes), but an
  // update replaces this whole file, this line included.
  // How to get a free key: see the README.
  // =====================================================================
  const API_KEY = 'PASTE_API_KEY_HERE';

  const MAX_EMBEDS = 3;
  const PER_TAB = 8; // candidates kept per search, so a duplicate across searches still leaves a fallback
  const MIN_SECONDS = 150; // drops shorts and most trailers
  const CACHE_MS = 3 * 24 * 3600 * 1000; // YouTube's API policy allows caching for up to 30 days
  const CACHE_VER = 'v3';
  const KEY_HELP = 'https://github.com/danieldanilov/deku-deals-videos#get-a-free-youtube-api-key';
  const JUNK = /\b(trailers?|teasers?|announce(ment)?|reveal(ed)?|official|cinematic|soundtrack|ost|all cutscenes|game movie|shorts?)\b|#shorts/i;
  const STOP = new Set(['the', 'a', 'an', 'of', 'and', 'to', 'in', 'on', 'for', 'edition', 'deluxe', 'definitive', 'complete', 'remastered', 'hd']);

  // ---------- game title ----------
  const rawTitle = (document.querySelector('.item-title')?.textContent ||
    document.title.replace(/\s*\|\s*Deku Deals.*$/i, '')).trim();
  if (!rawTitle) return;
  const isSwitch2 = /switch 2/i.test(rawTitle);
  const game = rawTitle
    .replace(new RegExp('[' + String.fromCharCode(0x2122, 0xae, 0xa9) + ']', 'g'), '') // TM, (R), (C); kept ASCII so a paste can't garble it
    .replace(/\s*\W?\s*Nintendo Switch(\s*2)?\s*Edition\s*$/i, '')
    .replace(/\s*\((Nintendo\s*)?Switch(\s*2)?\)\s*$/i, '')
    .replace(/\s+/g, ' ')
    .trim();

  // Says the video is about the Switch version (and not Mario's P-Switch)
  const SWITCH_TITLE = /nintendo switch|\bswitch\s*(1|2|oled|lite)\b|\bon (the )?switch\b|[([|]\s*switch\b|(^|\s)switch\s*(gameplay|review|performance|version|port|handheld|docked|edition)\b/i;

  // maxSeconds is soft: longer videos only fill in when too few short ones match.
  // mustMatch is hard: on Switch, a video has to say Switch in its title.
  const TABS = [
    { key: 'reviews', label: 'Reviews', q: `${game} review` },
    { key: 'gameplay', label: 'Gameplay', q: `${game} gameplay first hour`, maxSeconds: 3 * 3600 },
    { key: 'switch', label: isSwitch2 ? 'On Switch 2' : 'On Switch', q: `${game} ${isSwitch2 ? 'switch 2' : 'nintendo switch'} gameplay`, mustMatch: SWITCH_TITLE, maxSeconds: 3 * 3600 },
  ];

  // ---------- helpers ----------
  // "Hades II" and "Hades 2" match. I, V and X stay letters (Mega Man X).
  const ROMAN = { ii: '2', iii: '3', iv: '4', vi: '6', vii: '7', viii: '8', ix: '9' };
  const norm = (s) => String(s || '').normalize('NFKD').replace(/\p{M}/gu, '') // strip accents
    .toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim()
    .split(' ').map((w) => ROMAN[w] || w).join(' ');

  function relevance(videoTitle) {
    const v = ' ' + norm(videoTitle) + ' ';
    const g = norm(game);
    if (g && v.includes(' ' + g + ' ')) return 2;
    const words = g.split(' ').filter((w) => w && !STOP.has(w));
    if (!words.length) return 0;
    const hits = words.filter((w) => v.includes(' ' + w + ' ')).length;
    return hits / words.length >= 0.75 ? 1 : 0;
  }

  const toSeconds = (len) => (len || '').split(':').reduce((acc, p) => acc * 60 + (parseInt(p, 10) || 0), 0);

  // The API gives durations as ISO 8601 ("PT1H2M3S"); live and upcoming videos come back as "P0D".
  const isoSeconds = (d) => {
    const m = /^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/.exec(d || '');
    return m ? (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0) : 0;
  };
  const clock = (s) => {
    const pad = (n) => String(n).padStart(2, '0');
    const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
    return h ? `${h}:${pad(m)}:${pad(sec)}` : `${m}:${pad(sec)}`;
  };
  const ago = (iso) => {
    const days = (Date.now() - Date.parse(iso)) / 864e5;
    if (!(days >= 0)) return '';
    if (days >= 365) return `${Math.floor(days / 365)}y ago`;
    if (days >= 30) return `${Math.floor(days / 30)}mo ago`;
    if (days >= 7) return `${Math.floor(days / 7)}w ago`;
    return days >= 1 ? `${Math.floor(days)}d ago` : 'today';
  };
  // The API returns titles HTML-escaped ("Tom &amp; Jerry", "Don&#39;t")
  const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };
  const decodeEntities = (s) => String(s || '').replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (_, e) => {
    if (e[0] !== '#') return NAMED[e.toLowerCase()];
    return String.fromCodePoint(e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10));
  });

  // Titles that are mostly non-Latin script (the search asks for English results)
  const mostlyNonLatin = (s) => {
    const letters = s.match(/\p{L}/gu) || [];
    const latin = s.match(/\p{Script=Latin}/gu) || [];
    return letters.length > 0 && latin.length / letters.length < 0.7;
  };

  function pick(videos, tab) {
    const seen = new Set();
    const ok = videos
      .filter((v) => v.id && !seen.has(v.id) && seen.add(v.id))
      .filter((v) => v.length && toSeconds(v.length) >= MIN_SECONDS) // no length = live/upcoming
      .filter((v) => !JUNK.test(v.title) && !mostlyNonLatin(v.title))
      .filter((v) => !tab.mustMatch || tab.mustMatch.test(v.title))
      .map((v, i) => ({ ...v, rel: relevance(v.title), i }))
      .filter((v) => v.rel > 0)
      .sort((a, b) => b.rel - a.rel || a.i - b.i);
    if (!tab.maxSeconds) return ok.slice(0, PER_TAB);
    const short = ok.filter((v) => toSeconds(v.length) <= tab.maxSeconds);
    const long = ok.filter((v) => toSeconds(v.length) > tab.maxSeconds);
    return (short.length >= PER_TAB / 2 ? short : [...short, ...long]).slice(0, PER_TAB);
  }

  // ---------- YouTube Data API ----------
  // The key in the API_KEY line at the top wins; otherwise the one saved from the page's key field.
  const codeKey = API_KEY.trim() === 'PASTE_API_KEY_HERE' ? '' : API_KEY.trim();
  const getKey = () => codeKey || String(GM_getValue('apiKey', '') || '').trim();

  const gm = (opts) => new Promise((resolve, reject) => GM_xmlhttpRequest({
    timeout: 15000, ...opts, onload: resolve,
    onerror: () => reject(new Error('network error')), ontimeout: () => reject(new Error('timed out')),
  }));

  const API_BASE = 'https://www.googleapis.com/youtube/v3/';

  // Main route: the page's own fetch. Google's API allows browser calls from any site (CORS) and
  // takes the key in the X-Goog-Api-Key header, which keeps it out of the URL. Tampermonkey's
  // GM_xmlhttpRequest is not the main route because some WebKit browsers (Search) drop both the
  // query string and custom headers from it.
  const viaFetch = (method, params, key) =>
    fetch(API_BASE + method + '?' + new URLSearchParams(params), { headers: { 'X-Goog-Api-Key': key }, credentials: 'omit' })
      .then(async (r) => ({ status: r.status, responseText: await r.text() }));

  // Fallback if the page's fetch fails at the network level: Tampermonkey's request, parameters in
  // a POST body with "X-HTTP-Method-Override: GET".
  const viaGM = (method, params, key) => gm({
    method: 'POST',
    url: API_BASE + method,
    headers: { 'X-HTTP-Method-Override': 'GET', 'X-Goog-Api-Key': key, 'Content-Type': 'application/x-www-form-urlencoded' },
    data: new URLSearchParams(params).toString(),
  });

  function api(method, params, key) {
    return Promise.resolve().then(() => viaFetch(method, params, key)).catch(() => viaGM(method, params, key)).then((r) => {
      let body = null;
      try { body = JSON.parse(r.responseText); } catch (e) { /* not JSON */ }
      if (r.status === 200 && body) return body;
      const err = body?.error || {};
      const reasons = [err.status, ...(err.errors || []).map((x) => x.reason), ...(err.details || []).map((x) => x.reason)].join(' ');
      if (/quotaExceeded|dailyLimitExceeded|RESOURCE_EXHAUSTED/.test(reasons)) {
        throw Object.assign(new Error("today's free YouTube searches are used up; they reset at midnight Pacific time"), { quota: true });
      }
      if (/API_KEY_INVALID|keyInvalid/.test(reasons) || /API key not valid/i.test(err.message || '')) {
        throw Object.assign(new Error('YouTube rejected the API key'), { badKey: true });
      }
      if (/SERVICE_DISABLED|accessNotConfigured/.test(reasons)) {
        throw Object.assign(new Error("YouTube Data API v3 isn't enabled in the key's Google Cloud project"), { badKey: true });
      }
      if (/API_KEY_SERVICE_BLOCKED/.test(reasons)) {
        throw Object.assign(new Error('the API key is restricted to other APIs; add YouTube Data API v3 to its allowed APIs'), { badKey: true });
      }
      throw new Error(`${err.message || 'YouTube API answered ' + r.status} [HTTP ${r.status}]`);
    });
  }

  // One search (counts against the 100 free searches a day) plus one videos lookup for durations (1 unit).
  async function request(q, key) {
    const found = await api('search', { part: 'snippet', type: 'video', videoEmbeddable: 'true', maxResults: '25', relevanceLanguage: 'en', q }, key);
    const items = (found.items || []).filter((it) => it.id?.videoId);
    if (!items.length) return [];
    const details = await api('videos', { part: 'contentDetails', id: items.map((it) => it.id.videoId).join(',') }, key);
    const secs = {};
    (details.items || []).forEach((v) => { secs[v.id] = isoSeconds(v.contentDetails?.duration); });
    return items.map((it) => ({
      id: it.id.videoId,
      title: decodeEntities(it.snippet?.title),
      channel: decodeEntities(it.snippet?.channelTitle),
      length: secs[it.id.videoId] ? clock(secs[it.id.videoId]) : '',
      age: ago(it.snippet?.publishedAt),
    }));
  }

  function fetchVideos(tab, key) {
    const cacheKey = `yt:${CACHE_VER}:${tab.key}:${tab.q}`;
    const cached = GM_getValue(cacheKey, null);
    if (cached && Date.now() - cached.t < CACHE_MS) return Promise.resolve(cached.items);
    return request(tab.q, key).then((videos) => {
      const items = pick(videos, tab);
      GM_setValue(cacheKey, { t: Date.now(), items });
      return items;
    });
  }

  const el = (tag, attrs = {}, ...kids) => {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k === 'class') n.className = v;
      else if (k === 'text') n.textContent = v;
      else if (k.startsWith('on')) n.addEventListener(k.slice(2), v);
      else n.setAttribute(k, v);
    }
    kids.flat().forEach((c) => c && n.append(c));
    return n;
  };

  // ---------- styles ----------
  document.head.append(el('style', { text: `
    #ddv { margin: 0 0 1rem; }
    #ddv .ddv-head { display: flex; align-items: center; gap: .5rem; margin-bottom: .6rem; }
    #ddv .ddv-head h3 { margin: 0; flex: 1; }
    #ddv .ddv-btn { font: inherit; font-size: .9rem; color: inherit; background: transparent;
      border: 1px solid rgba(127,127,127,.35); border-radius: 999px; padding: .2rem .8rem; cursor: pointer; }
    /* Odd count: the first video (the review) spans the full width, the rest sit two across. */
    #ddv .ddv-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem .75rem; }
    #ddv .ddv-item { min-width: 0; }
    #ddv .ddv-item:first-child:nth-last-child(odd) { grid-column: 1 / -1; }
    @media (max-width: 575px) { #ddv .ddv-grid { grid-template-columns: 1fr; } }
    #ddv .ddv-player { position: relative; aspect-ratio: 16 / 9; background: #000; border-radius: 8px; overflow: hidden; }
    #ddv .ddv-player iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
    #ddv .ddv-cap { font-size: .85rem; line-height: 1.3; margin-top: .35rem; }
    #ddv .ddv-kind { font-size: .7rem; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; opacity: .65; }
    #ddv .ddv-t { display: block; color: inherit; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    #ddv .ddv-meta { font-size: .78rem; opacity: .7; }
    #ddv .ddv-msg { opacity: .85; padding: .5rem 0; grid-column: 1 / -1; }
    #ddv .ddv-keyrow { display: flex; flex-wrap: wrap; gap: .5rem; margin-top: .5rem; align-items: center; }
    #ddv .ddv-input { flex: 1; min-width: 220px; font: inherit; font-size: .9rem; color: inherit; background: transparent;
      border: 1px solid rgba(127,127,127,.45); border-radius: 6px; padding: .3rem .6rem; }
    #ddv.ddv-collapsed .ddv-body { display: none; }
  ` }));

  // ---------- UI ----------
  const toggle = el('button', { class: 'ddv-btn', type: 'button' });
  const grid = el('div', { class: 'ddv-grid' });
  const section = el('section', { id: 'ddv' },
    el('div', { class: 'ddv-head' }, el('h3', { text: 'Videos' }), toggle),
    el('div', { class: 'ddv-body' }, grid),
  );

  const anchor = document.getElementById('price-history');
  if (anchor) {
    const hr = anchor.previousElementSibling?.tagName === 'HR' ? anchor.previousElementSibling : anchor;
    hr.before(el('hr', { class: 'mt-0' }), section);
  } else {
    const head = document.querySelector('.item-title')?.closest('.clearfix') || document.querySelector('main');
    if (!head) return;
    head.after(section);
  }

  let collapsed = GM_getValue('collapsed', false);
  const applyCollapsed = () => {
    section.classList.toggle('ddv-collapsed', collapsed);
    toggle.textContent = collapsed ? 'Show' : 'Hide';
  };
  toggle.addEventListener('click', () => { collapsed = !collapsed; GM_setValue('collapsed', collapsed); applyCollapsed(); });
  applyCollapsed();

  const message = (text, ...extra) => grid.replaceChildren(el('div', { class: 'ddv-msg' }, el('div', { text }), ...extra));
  const keyHelpButton = () => el('a', { class: 'ddv-btn', href: KEY_HELP, target: '_blank', rel: 'noopener', text: 'How to get a free key' });

  // A key typed into the page is saved in Tampermonkey's storage for this script, which survives updates.
  // An inline field, not prompt(): some WebKit browsers (Search) mishandle prompt() from userscripts.
  function keyForm(intro) {
    const input = el('input', { class: 'ddv-input', type: 'password', placeholder: 'Paste your YouTube API key', autocomplete: 'off', spellcheck: 'false' });
    const save = () => {
      const k = input.value.trim();
      if (!k) return input.focus();
      GM_setValue('apiKey', k);
      load();
    };
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') save(); });
    message(intro, el('div', { class: 'ddv-keyrow' }, input, el('button', { class: 'ddv-btn', type: 'button', text: 'Save key', onclick: save }), keyHelpButton()));
    input.focus({ preventScroll: true });
  }
  if (typeof GM_registerMenuCommand === 'function') {
    GM_registerMenuCommand('Set YouTube API key', () => { collapsed = false; applyCollapsed(); keyForm('Paste a new YouTube API key.'); });
  }

  function player(v, kind) {
    return el('div', { class: 'ddv-item' },
      el('div', { class: 'ddv-player' },
        el('iframe', {
          src: `https://www.youtube-nocookie.com/embed/${v.id}?rel=0`,
          loading: 'lazy',
          allow: 'encrypted-media; picture-in-picture; fullscreen',
          allowfullscreen: '',
          referrerpolicy: 'strict-origin-when-cross-origin',
          title: v.title,
        })),
      el('div', { class: 'ddv-cap' },
        el('span', { class: 'ddv-kind', text: kind }),
        el('a', { class: 'ddv-t', href: `https://www.youtube.com/watch?v=${v.id}`, target: '_blank', rel: 'noopener', title: v.title, text: v.title }),
        el('span', { class: 'ddv-meta', text: [v.channel, v.length, v.age].filter(Boolean).join(' ' + String.fromCharCode(0xb7) + ' ') })));
  }

  // Top review, top gameplay, top Switch video. An empty slot is filled by the next review or gameplay video.
  async function load() {
    const key = getKey();
    if (!key) return keyForm('This needs a free YouTube Data API key (about 33 new games a day).');
    message('Finding videos...');
    const results = await Promise.allSettled(TABS.map((t) => fetchVideos(t, key)));
    const [reviews, gameplay, onSwitch] = results.map((r) => (r.status === 'fulfilled' ? r.value : []));
    const used = new Set();
    const slots = [];
    const add = (list, kind) => {
      if (slots.length >= MAX_EMBEDS) return;
      const v = list.find((x) => !used.has(x.id));
      if (v) { used.add(v.id); slots.push(player(v, kind)); }
    };
    add(reviews, 'Review');
    add(gameplay, 'Gameplay');
    add(onSwitch, TABS[2].label);
    [[reviews, 'Review'], [gameplay, 'Gameplay'], [reviews, 'Review']].forEach(([list, kind]) => add(list, kind));

    if (slots.length) return grid.replaceChildren(...slots);
    const err = results.find((r) => r.status === 'rejected')?.reason;
    if (!err) return message(`No reviews or gameplay found for "${game}" once trailers were filtered out.`);
    if (err.badKey) return keyForm(`Couldn't load videos: ${err.message}. Paste a working key:`);
    message(`Couldn't load videos: ${err.message || err}.`);
  }
  load();
})();

