// Runs the userscript's logic in a sandbox with a fake page, a fake YouTube Data API and fake
// Tampermonkey functions. All games, channels and videos here are made up.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const SCRIPT = fileURLToPath(new URL('../deku-deals-videos.user.js', import.meta.url));
const raw = readFileSync(SCRIPT, 'utf8');
// Stop the script just before it touches the page's styles, and hand its internals to the tests.
const src = raw.replace('// ---------- styles ----------',
  'globalThis.__t = { request, pick, TABS, relevance, isoSeconds, clock, decodeEntities, getKey, game }; throw "stop";');

let failed = 0;
const ok = (cond, msg) => { console.log(`${cond ? 'PASS' : 'FAIL'} ${msg}`); if (!cond) failed++; };

function load({ title = 'Starfall Odyssey', fetchImpl, xhr, store = {}, source = src } = {}) {
  const ctx = {
    document: { querySelector: () => ({ textContent: title }), title: '' },
    URLSearchParams,
    fetch: fetchImpl || (async () => { throw new TypeError('no fetch in this test'); }),
    GM_getValue: (k, d) => (k in store ? store[k] : d),
    GM_setValue: (k, v) => { store[k] = v; },
    GM_xmlhttpRequest: xhr || (() => { throw new Error('GM_xmlhttpRequest should not be called'); }),
  };
