  try { vm.runInContext(source, ctx); } catch (e) { if (e !== 'stop') throw e; }
  return ctx.__t;
}

// ---------- fake API data ----------
const daysAgo = (n) => new Date(Date.now() - n * 864e5).toISOString();
const VIDEOS = [
  ['vidReview01', 'Starfall Odyssey Review', 'Pixel Weekly', 'PT14M5S', 420],
  ['vidBefore01', 'Starfall Odyssey - Before You Buy', 'Game Notes', 'PT11M40S', 410],
  ['vidTrailr01', 'Starfall Odyssey Launch Trailer', 'Publisher', 'PT2M31S', 500],
  ['vidOffcl001', 'Starfall Odyssey Official Gameplay Overview', 'Publisher', 'PT8M10S', 480],
  ['vidShort001', 'Starfall Odyssey in 30 seconds #shorts', 'Quick Clips', 'PT30S', 30],
  ['vidLive0001', 'Starfall Odyssey LIVE review stream', 'Live Guy', 'P0D', 0],
  ['vidOther001', 'Starfall Legends Review', 'Pixel Weekly', 'PT12M', 300],
  ['vidLatin001', 'スターフォール オデッセイ Starfall Odyssey', 'JP Channel', 'PT20M', 200],
  ['vidEntity01', 'Starfall Odyssey Review &amp; Why It&#39;s &quot;Great&quot;', 'Tom &amp; Jerry Plays', 'PT1H7M58S', 40],
  ['vidSwitch01', 'Starfall Odyssey Nintendo Switch 2 Gameplay', 'Handheld Lab', 'PT25M', 90],
  ['vidPSwitch1', 'Starfall Odyssey - All 40 P-Switch Locations', 'Guides', 'PT18M', 95],
  ['vidLong0001', 'Starfall Odyssey Full Game Walkthrough', 'Longplays', 'PT9H12M', 100],
  ['vidPart0001', 'Starfall Odyssey Gameplay Part 1', 'Lets Play', 'PT45M', 120],
];
const searchBody = JSON.stringify({ items: VIDEOS.map(([id, title, channel, , age]) => ({
  id: { kind: 'youtube#video', videoId: id }, snippet: { title, channelTitle: channel, publishedAt: daysAgo(age) } })) });
const videosBody = JSON.stringify({ items: VIDEOS.map(([id, , , duration]) => ({ id, contentDetails: { duration } })) });
const apiFetch = (seen = []) => async (url, opts) => {
  seen.push({ url, opts });
  return { status: 200, text: async () => (/\/search\?/.test(url) ? searchBody : videosBody) };
};
const apiError = (status, body) => async () => ({ status, text: async () => (typeof body === 'string' ? body : JSON.stringify(body)) });
const googleError = (code, status, reason, detail, message) =>
  ({ error: { code, message: message || reason, status, errors: [{ reason }], details: detail ? [{ reason: detail }] : [] } });
const failsWith = async (t) => { try { await t.request('q', 'k'); return null; } catch (e) { return e; } };

// ---------- the file itself ----------
ok([...raw].every((c) => c.charCodeAt(0) < 128), 'script is pure ASCII, so a mis-encoded paste cannot garble it');
ok(/const API_KEY = 'PASTE_API_KEY_HERE';/.test(raw) && !/AIza[0-9A-Za-z_-]{20,}/.test(raw), 'ships with the placeholder and no real API key');
ok(/@connect\s+www\.googleapis\.com/.test(raw) && !/youtube\.com\/results|ytInitialData|youtubei/.test(raw), 'talks only to the official API, no page scraping');
const rawUrl = 'https://raw.githubusercontent.com/danieldanilov/deku-deals-videos/main/deku-deals-videos.user.js';
ok(raw.includes(`@updateURL    ${rawUrl}`) && raw.includes(`@downloadURL  ${rawUrl}`), 'update and download URLs point at this repo');

// ---------- requests ----------
{
  const seen = [];
  const t = load({ fetchImpl: apiFetch(seen) });
  const vids = await t.request('Starfall Odyssey review', 'TESTKEY123');
  const u = new URL(seen[0].url);
  ok(seen.length === 2 && vids.length === VIDEOS.length, 'one search plus one videos lookup');
  ok(u.origin + u.pathname === 'https://www.googleapis.com/youtube/v3/search' && u.searchParams.get('q') === 'Starfall Odyssey review'
    && u.searchParams.get('type') === 'video' && u.searchParams.get('videoEmbeddable') === 'true', 'search asks for embeddable videos only');
  ok(new URL(seen[1].url).searchParams.get('id').split(',').length === VIDEOS.length, 'durations for every result in one call');
  ok(!seen.some((s) => s.url.includes('TESTKEY123')) && seen.every((s) => s.opts.headers['X-Goog-Api-Key'] === 'TESTKEY123'),
    'key goes in the X-Goog-Api-Key header, never the URL');
  ok(seen.every((s) => s.opts.credentials === 'omit'), 'no cookies sent to Google');

  const byId = Object.fromEntries(vids.map((v) => [v.id, v]));
  ok(byId.vidReview01.length === '14:05' && byId.vidLong0001.length === '9:12:00' && /y ago$/.test(byId.vidReview01.age), 'durations and ages formatted');
  ok(byId.vidEntity01.title === 'Starfall Odyssey Review & Why It\'s "Great"' && byId.vidEntity01.channel === 'Tom & Jerry Plays', 'HTML entities in titles decoded');
  ok(byId.vidLive0001.length === '', 'live streams get no length');

  const reviews = t.pick(vids, t.TABS[0]).map((v) => v.id);
  ok(reviews[0] === 'vidReview01' && reviews.includes('vidEntity01'), 'reviews keep real reviews, in search order');
  ok(!['vidTrailr01', 'vidOffcl001', 'vidShort001', 'vidLive0001', 'vidOther001', 'vidLatin001'].some((id) => reviews.includes(id)),
    'drops trailers, official promo videos, shorts, live streams, other games and non-English titles');
  ok(!t.pick(vids, t.TABS[1]).some((v) => v.id === 'vidTrailr01' || v.id === 'vidOffcl001'), 'trailers and promo videos stay out of gameplay too');
  const onSwitch = t.pick(vids, t.TABS[2]).map((v) => v.id);
  ok(onSwitch.join() === 'vidSwitch01', 'Switch slot needs the Switch version in the title (P-Switch does not count)');
  const gameplay = t.pick(vids, t.TABS[1]).map((v) => v.id);
  ok(gameplay.includes('vidPart0001') && !gameplay.includes('vidLong0001'), 'gameplay leaves out walkthroughs over 3 hours when enough shorter videos exist');
  const few = vids.filter((v) => ['vidPart0001', 'vidLong0001'].includes(v.id));
  ok(t.pick(few, t.TABS[1]).map((v) => v.id).join() === 'vidPart0001,vidLong0001', 'and uses them as a last resort when there are too few');
}

// ---------- matching game titles ----------
{
  const hades = load({ title: 'Hades II' });
  ok(hades.relevance('Hades 2 Review') === 2 && hades.relevance('Hades Review') === 0, '"Hades II" matches "Hades 2" but not the first game');
  const zelda = load({ title: 'The Legend of Zelda: Tears of the Kingdom' });
  ok(zelda.relevance('Zelda Tears of the Kingdom Review') === 1 && zelda.relevance('Zelda Breath of the Wild Review') === 0, 'partial titles match, other games in a series do not');
  const edition = load({ title: 'Starfall Odyssey - Nintendo Switch 2 Edition' });
  ok(edition.game === 'Starfall Odyssey' && edition.TABS[2].label === 'On Switch 2', 'Switch 2 Edition is stripped from the search and labels the Switch slot');
  const t = load();
  ok(t.isoSeconds('PT1H2M3S') === 3723 && t.isoSeconds('P1DT1S') === 86401 && t.isoSeconds('P0D') === 0 && t.clock(5) === '0:05', 'ISO durations and clock format');
}

// ---------- errors from Google ----------
{
  let e = await failsWith(load({ fetchImpl: apiError(403, googleError(403, 'PERMISSION_DENIED', 'quotaExceeded')) }));
  ok(e?.quota && /used up/.test(e.message), 'daily quota used up: says when it resets');
  e = await failsWith(load({ fetchImpl: apiError(400, googleError(400, 'INVALID_ARGUMENT', 'badRequest', 'API_KEY_INVALID', 'API key not valid. Please pass a valid API key.')) }));
  ok(e?.badKey, 'invalid key: asks for a new one');
  e = await failsWith(load({ fetchImpl: apiError(403, googleError(403, 'PERMISSION_DENIED', 'accessNotConfigured', 'SERVICE_DISABLED')) }));
  ok(e?.badKey && /isn't enabled/.test(e.message), 'API not enabled in the project: says so');
  e = await failsWith(load({ fetchImpl: apiError(403, googleError(403, 'PERMISSION_DENIED', 'forbidden', 'API_KEY_SERVICE_BLOCKED')) }));
  ok(e?.badKey && /restricted/.test(e.message), 'key restricted to other APIs: says so');
  e = await failsWith(load({ fetchImpl: apiError(500, '<html>oops</html>') }));
  ok(e && /500/.test(e.message) && !e.badKey, 'server error reported with its status');
}

// ---------- fallback route ----------
{
  const calls = [];
  const t = load({
    fetchImpl: async () => { throw new TypeError('Load failed'); },
    xhr: (o) => { calls.push(o); setTimeout(() => o.onload({ status: 200, responseText: /\/search$/.test(o.url) ? searchBody : videosBody }), 0); },
  });
  ok((await t.request('q', 'k')).length === VIDEOS.length && calls[0].method === 'POST' && calls[0].headers['X-HTTP-Method-Override'] === 'GET',
    'page fetch blocked: falls back to Tampermonkey\'s request');
  const seen = [];
  const empty = load({ fetchImpl: async (url) => { seen.push(url); return { status: 200, text: async () => '{"items":[]}' }; } });
  ok((await empty.request('q', 'k')).length === 0 && seen.length === 1, 'no results: skips the durations call');
}

// ---------- where the key comes from ----------
{
  ok(load().getKey() === '', 'no key anywhere: the page shows the key field');
  ok(load({ store: { apiKey: '  STORED  ' } }).getKey() === 'STORED', 'key saved from the page field is used, trimmed');
  const withKey = src.replace("const API_KEY = 'PASTE_API_KEY_HERE';", "const API_KEY = ' CODEKEY ';");
  ok(load({ source: withKey, store: { apiKey: 'STORED' } }).getKey() === 'CODEKEY', 'a key typed into the API_KEY line wins');
}

console.log(failed ? `\n${failed} failed` : '\nall passed');
process.exit(failed ? 1 : 0);

