/**
 * Monarch Money API - Transaction Operations
 * Functions for querying, updating, and deleting transactions
 */

import { debugLog } from '../core/utils';
import { callMonarchGraphQL } from './monarch';

// ============================================================
// Interfaces
// ============================================================

interface TransactionCategory {
  id: string;
  name: string;
  icon: string;
  group: {
    id: string;
    type: string;
    __typename?: string;
  };
  __typename?: string;
}

interface TransactionMerchant {
  name: string;
  id: string;
  transactionsCount: number;
  logoUrl: string | null;
  recurringTransactionStream: {
    frequency: string;
    isActive: boolean;
    __typename?: string;
  } | null;
  __typename?: string;
}

interface TransactionTag {
  id: string;
  name: string;
  color: string;
  order: number;
  __typename?: string;
}

interface TransactionAccount {
  id: string;
  displayName: string;
  icon: string;
  logoUrl: string | null;
  __typename?: string;
}

interface MonarchTransaction {
  id: string;
  amount: number;
  pending: boolean;
  date: string;
  hideFromReports: boolean;
  hiddenByAccount: boolean;
  plaidName: string;
  notes: string;
  isRecurring: boolean;
  reviewStatus: string | null;
  needsReview: boolean;
  isSplitTransaction: boolean;
  dataProviderDescription: string;
  attachments: Array<{ id: string; __typename?: string }>;
  goal: { id: string; name: string; __typename?: string } | null;
  savingsGoalEvent: {
    id: string;
    goal: { id: string; name: string; __typename?: string };
    __typename?: string;
  } | null;
  category: TransactionCategory;
  merchant: TransactionMerchant;
  tags: TransactionTag[];
  account: TransactionAccount;
  ownedByUser: {
    id: string;
    displayName: string;
    profilePictureUrl: string | null;
    __typename?: string;
  } | null;
  /**
   * Timestamp of an explicit ownership decision, or null when ownership is
   * inherited from the account.
   *
   * This is the ONLY way to tell a deliberate "Shared" choice from "never
   * touched": both report `ownedByUser: null`, but only the former has this
   * field set. Anything wanting to avoid overwriting a user's choice must check
   * it — see `services/common/ownerSync`.
   */
  ownershipOverriddenAt: string | null;
  __typename?: string;
}

interface GetTransactionsListOptions {
  accountIds: string[];
  startDate: string;
  endDate: string;
  tags?: string[] | null;
  limit?: number;
  offset?: number;
  orderBy?: string;
  transactionVisibility?: string;
}

interface TransactionListResult {
  totalCount: number;
  totalSelectableCount: number;
  results: MonarchTransaction[];
}

interface HouseholdTransactionTag {
  id: string;
  name: string;
  color: string;
  order: number;
  transactionCount?: number;
  __typename?: string;
}

interface GetHouseholdTransactionTagsOptions {
  search?: string | null;
  limit?: number | null;
  bulkParams?: Record<string, unknown> | null;
  includeTransactionCount?: boolean;
}

interface UpdateTransactionInput {
  amount?: number;
  notes?: string;
  category?: string;
  hideFromReports?: boolean;
  needsReview?: boolean;
  date?: string;
  [key: string]: unknown;
}

interface UpdatedTransaction {
  id: string;
  amount: number;
  pending: boolean;
  date: string;
  notes: string;
  category: { id: string; __typename?: string };
  merchant: { id: string; name: string; __typename?: string };
  tags: TransactionTag[];
  account: TransactionAccount;
  __typename?: string;
  [key: string]: unknown;
}

interface SetTransactionTagsResult {
  id: string;
  tags: Array<{ id: string; __typename?: string }>;
  __typename?: string;
}

// ============================================================
// Functions
// ============================================================

/**
 * Get transactions list from Monarch
 * Uses the Web_GetTransactionsList operation to retrieve filtered transactions.
 * @param options - Query options
 * @returns Transaction list with totalCount and results
 * @throws If required parameters are missing or API call fails
 */
export async function getTransactionsList(options: GetTransactionsListOptions): Promise<TransactionListResult> {
  const {
    accountIds,
    startDate,
    endDate,
    tags = null,
    limit = 100,
    offset = 0,
    orderBy = 'date',
    transactionVisibility = 'all_transactions',
  } = options || {};

  // Validate required parameters
  if (!accountIds || !Array.isArray(accountIds) || accountIds.length === 0) {
    throw new Error('accountIds is required and must be a non-empty array');
  }

  if (!startDate) {
    throw new Error('startDate is required (format: YYYY-MM-DD)');
  }

  if (!endDate) {
    throw new Error('endDate is required (format: YYYY-MM-DD)');
  }

  // Build filters object
  const filters: Record<string, unknown> = {
    accounts: accountIds,
    startDate,
    endDate,
    transactionVisibility,
  };

  // Add optional tags filter
  if (tags && Array.isArray(tags) && tags.length > 0) {
    filters.tags = tags;
  }

  debugLog('Getting transactions list with filters:', filters);

  const query = `query Web_GetTransactionsList($offset: Int, $limit: Int, $filters: TransactionFilterInput, $orderBy: TransactionOrdering) {
  allTransactions(filters: $filters) {
    totalCount
    totalSelectableCount
    results(offset: $offset, limit: $limit, orderBy: $orderBy) {
      id
      ...TransactionOverviewFields
      __typename
    }
    __typename
  }
}

fragment TransactionOverviewFields on Transaction {
  id
  amount
  pending
  date
  hideFromReports
  hiddenByAccount
  plaidName
  notes
  isRecurring
  reviewStatus
  needsReview
  isSplitTransaction
  dataProviderDescription
  attachments {
    id
    __typename
  }
  goal {
    id
    name
    __typename
  }
  savingsGoalEvent {
    id
    goal {
      id
      name
      __typename
    }
    __typename
  }
  category {
    id
    name
    icon
    group {
      id
      type
      __typename
    }
    __typename
  }
  merchant {
    name
    id
    transactionsCount
    logoUrl
    recurringTransactionStream {
      frequency
      isActive
      __typename
    }
    __typename
  }
  tags {
    id
    name
    color
    order
    __typename
  }
  account {
    id
    displayName
    icon
    logoUrl
    __typename
  }
  ownedByUser {
    id
    displayName
    profilePictureUrl
    __typename
  }
  ownershipOverriddenAt
  __typename
}`;

  const variables = {
    offset,
    limit,
    filters,
    orderBy,
  };

  const data = await callMonarchGraphQL('Web_GetTransactionsList', query, variables);

  debugLog(`Retrieved ${data.allTransactions.results.length} transactions (total: ${data.allTransactions.totalCount})`);

  return {
    totalCount: data.allTransactions.totalCount,
    totalSelectableCount: data.allTransactions.totalSelectableCount,
    results: data.allTransactions.results,
  };
}

/**
 * Get household transaction tags from Monarch
 * @param options - Query options
 * @returns Array of transaction tags
 */
export async function getHouseholdTransactionTags(options: GetHouseholdTransactionTagsOptions = {}): Promise<HouseholdTransactionTag[]> {
  const {
    search = null,
    limit = null,
    bulkParams = null,
    includeTransactionCount = false,
  } = options;

  const variables: Record<string, unknown> = {
    includeTransactionCount,
  };

  if (search !== null) {
    variables.search = search;
  }

  if (limit !== null) {
    variables.limit = limit;
  }

  if (bulkParams !== null) {
    variables.bulkParams = bulkParams;
  }

  debugLog('Getting household transaction tags with options:', variables);

  const query = `query Common_GetHouseholdTransactionTags($search: String, $limit: Int, $bulkParams: BulkTransactionDataParams, $includeTransactionCount: Boolean = false) {
  householdTransactionTags(
    search: $search
    limit: $limit
    bulkParams: $bulkParams
  ) {
    id
    name
    color
    order
    transactionCount @include(if: $includeTransactionCount)
    __typename
  }
}`;

  const data = await callMonarchGraphQL('Common_GetHouseholdTransactionTags', query, variables);

  debugLog(`Retrieved ${data.householdTransactionTags?.length || 0} transaction tags`);

  return data.householdTransactionTags || [];
}

/**
 * Get a tag by name (case-insensitive)
 * @param tagName - Tag name to search for
 * @returns Tag object or null if not found
 */
export async function getTagByName(tagName: string): Promise<HouseholdTransactionTag | null> {
  if (!tagName || typeof tagName !== 'string') {
    throw new Error('Tag name is required and must be a string');
  }

  debugLog(`Looking up tag by name: ${tagName}`);

  const tags = await getHouseholdTransactionTags();
  const normalizedSearchName = tagName.toLowerCase().trim();

  const matchingTag = tags.find(
    (tag) => tag.name.toLowerCase().trim() === normalizedSearchName,
  );

  if (matchingTag) {
    debugLog(`Found tag: ${matchingTag.name} (ID: ${matchingTag.id})`);
  } else {
    debugLog(`Tag not found: ${tagName}`);
  }

  return matchingTag || null;
}

/**
 * Update a transaction's details
 * Uses the Web_TransactionDrawerUpdateTransaction mutation to modify transaction properties.
 * @param transactionId - Transaction ID to update (required)
 * @param updates - Fields to update
 * @returns Updated transaction object
 * @throws If transaction ID is missing or update fails
 */
export async function updateTransaction(transactionId: string, updates: UpdateTransactionInput = {}): Promise<UpdatedTransaction> {
  if (!transactionId) {
    throw new Error('Transaction ID is required');
  }

  const input = {
    id: transactionId,
    ...updates,
  };

  debugLog('Updating transaction:', input);

  const query = `mutation Web_TransactionDrawerUpdateTransaction($input: UpdateTransactionMutationInput!) {
  updateTransaction(input: $input) {
    transaction {
      id
      ...TransactionDrawerFields
      __typename
    }
    errors {
      ...PayloadErrorFields
      __typename
    }
    __typename
  }
}

