    path.setAttribute(
      'd',
      'M12.78 5.22a.749.749 0 0 1 0 1.06l-4.25 4.25a.749.749 0 0 1-1.06 0L3.22 6.28a.749.749 0 1 1 1.06-1.06L8 8.939l3.72-3.719a.749.749 0 0 1 1.06 0Z',
    );
    svg.appendChild(path);
    return svg;
  }

  function makeButton(s) {
    const btn = document.createElement('button');
    btn.id = s.id;
    btn.type = 'button';
    btn.className = 'Box-btn-octicon btn-octicon';
    btn.appendChild(chevron());
    btn.addEventListener('click', () => {
      s.folded = !s.folded;
      localStorage.setItem(s.key, s.folded ? '1' : '0');
      apply(s);
    });
    return btn;
  }

  // ---------- Main pass (GitHub navigates with Turbo) ----------
  function run() {
    for (const s of SECTIONS) {
      if (document.getElementById(s.id)) continue;
      const btn = makeButton(s);
      if (s.mount(btn)) apply(s);
    }
  }

  SECTIONS.forEach(apply);
  let queued = false;
  new MutationObserver(() => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => {
      queued = false;
      run();
    });
  }).observe(document.documentElement, { childList: true, subtree: true });
})();

